  XCircle,
  Clock,
  User,
  ChevronRight,
  ChevronLeft,
  ChevronDown,
  ChevronUp,
  Loader2,
  BookOpen,
  PenTool,
  ScrollText,
  Code2,
  Key,
  Users,
  AlertTriangle,
  MonitorSmartphone,
  Plus,
  Minus,
  Trash2,
  FileText,
  RotateCcw,
  X,
  Maximize2,
  TerminalSquare,
  Square,
  Trash,
  Lock,
  Unlock,
  EyeOff,
