  Copy,
  Check,
  Sun,
  Moon,
  Terminal,
  PanelRightClose,
  PanelRightOpen,
  Edit,
  AppWindow,
  RefreshCw,
  FolderKanban,
  BrainCircuit,
  Search,
  Download,
  Beaker,
  Terminal as TerminalIcon,
  Settings,
  ZoomIn,
  ZoomOut,
  Maximize,
  Minimize,
  Mail,
} from "lucide-react";

// --- FIREBASE SETUP ---
import { initializeApp } from "firebase/app";
import {
  getAuth,
  signInWithEmailAndPassword,
  createUserWithEmailAndPassword,
  onAuthStateChanged,
} from "firebase/auth";
import {
  getFirestore,
  collection,
  addDoc,
  onSnapshot,
  doc,
  setDoc,
  getDoc,
  updateDoc,
  increment,
  query,
  orderBy,
  serverTimestamp,
  arrayUnion,
  where,
  deleteDoc,
} from "firebase/firestore";

const firebaseConfig = {
    apiKey: "AIzaSyAaCrlH3D8D53r09HO9dgoFPVFDvanbxc4",
  authDomain: "zera-d9baf.firebaseapp.com",
  projectId: "zera-d9baf",
  storageBucket: "zera-d9baf.firebasestorage.app",
  messagingSenderId: "639985665820",
  appId: "1:639985665820:web:91f99f56a82314da481cd9",
  measurementId: "G-BCZMR9NC96",

};

const app = initializeApp(firebaseConfig);
const auth = getAuth(app);
const db = getFirestore(app);

// --- GROQ API ENGINE ---
const groqConfigs = [
  {
    key: "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",
    model: "llama-3.3-70b-versatile",
  },
  {
    key: "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",
    model: "llama-3.1-8b-instant",
  },
  {
    key: "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",
    model: "llama-3.3-70b-versatile",
  },
];

let currentApiNodeIndex = Math.floor(Math.random() * groqConfigs.length);

async function callGroq(prompt, maxRetries = 3) {
  let lastError;

  for (let attempt = 0; attempt < maxRetries; attempt++) {
    for (let i = 0; i < groqConfigs.length; i++) {
      const config =
        groqConfigs[(currentApiNodeIndex + i) % groqConfigs.length];

      try {
        const response = await fetch(
          "https://api.groq.com/openai/v1/chat/completions",
          {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
              Authorization: `Bearer ${config.key}`,
            },
            body: JSON.stringify({
              model: config.model,
              messages: [
                {
                  role: "system",
                  content:
                    "You are a strict, deterministic code execution engine and compiler. You execute code flawlessly. CRITICAL FOR PATTERNS: If the code prints ASCII art, shapes (like a butterfly), or uses string multiplication (e.g., '*' * i + ' ' * space + '*' * i), you MUST trace the exact mathematical character count for EVERY single line. NEVER skip the right side of the shape. NEVER truncate spaces. DO NOT approximate. CRITICAL: You MUST output ALL lines generated by loops. If a countdown loop goes to 1, you MUST print the line for 1. NEVER terminate output prematurely. Output ONLY the raw stdout/stderr text without markdown formatting unless specifically instructed to return JSON. If loops exceed 1000 iterations, throw a TimeoutException. UNDER NO CIRCUMSTANCES SHOULD YOU EXPLAIN THE CODE OR PROVIDE CONVERSATIONAL TEXT. IF THE CODE PRODUCES NO OUTPUT, RETURN AN EMPTY STRING.",
                },
                { role: "user", content: prompt },
              ],
              temperature: 0.05,
              max_tokens: 4096,
              top_p: 1,
            }),
          }
        );

        if (!response.ok) {
          const errData = await response.json().catch(() => ({}));
          if (response.status === 429) throw new Error("Rate Limited");
          throw new Error(
            `API ${config.model} Failed: ${
              errData.error?.message || response.status
            }`
          );
        }

        const data = await response.json();
        currentApiNodeIndex = (currentApiNodeIndex + 1) % groqConfigs.length;

        return data.choices?.[0]?.message?.content || "";
      } catch (error) {
        console.warn(
          `Execution Node Fallback: Key/Model failed (${config.model}). Shifting...`,
          error.message
        );
        lastError = error;
        continue;
      }
    }
    console.warn(
      `All execution nodes busy. Retrying attempt ${attempt + 1} in ${Math.pow(
        2,
        attempt
      )}s...`
    );
    await new Promise((resolve) =>
      setTimeout(resolve, 1000 * Math.pow(2, attempt))
    );
  }

  throw new Error(
    `Critical: All execution nodes exhausted or heavily rate-limited. Last error: ${lastError?.message}`
  );
}

// --- SYNTAX HIGHLIGHTING ENGINE (One Dark Pro Inspired) ---
const highlightCode = (code, language) => {
  if (!code) return "";
  let text = code
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
  const placeholders = [];
  let phIndex = 0;

  const addPh = (html) => {
    placeholders.push(html);
    return `__PH${phIndex++}__`;
  };

  text = text.replace(/(["'])(?:(?=(\\?))\2.)*?\1/g, (match) =>
    addPh(`<span class="text-[#98c379]">${match}</span>`)
  );
  text = text.replace(/(\/\/.*|#.*)/g, (match) =>
    addPh(`<span class="text-[#5c6370] italic">${match}</span>`)
  );
  text = text.replace(/(\/\*[\s\S]*?\*\/)/g, (match) =>
    addPh(`<span class="text-[#5c6370] italic">${match}</span>`)
  );

  text = text.replace(
    /\b(true|false|null|None|True|False|nullptr)\b/g,
    (match) => addPh(`<span class="text-[#d19a66]">${match}</span>`)
  );

  // Class/Type Names (Capitalized words)
  text = text.replace(/\b([A-Z][a-zA-Z0-9_]*)\b/g, (match) =>
    addPh(`<span class="text-[#e5c07b]">${match}</span>`)
  );

  text = text.replace(/(^\s*#\s*\w+)/gm, (match) =>
    addPh(`<span class="text-[#c678dd]">${match}</span>`)
  ); // Directives
  text = text.replace(/\b([a-zA-Z_]\w*)(?=\s*\()/g, (match) =>
    addPh(`<span class="text-[#61afef]">${match}</span>`)
  ); // Functions

  const kw = {
    python: [
      "def",
      "class",
      "if",
      "elif",
      "else",
      "while",
      "for",
      "in",
      "return",
      "import",
      "from",
      "as",
      "pass",
      "and",
      "or",
      "not",
      "print",
      "self",
      "yield",
      "try",
      "except",
      "with",
    ],
    java: [
      "public",
      "private",
      "protected",
      "static",
      "final",
      "void",
      "class",
      "interface",
      "import",
      "package",
      "new",
      "return",
      "if",
      "else",
      "for",
      "while",
      "boolean",
      "int",
      "double",
      "String",
      "System",
      "out",
      "println",
      "try",
      "catch",
    ],
    "c++": [
      "int",
      "float",
      "double",
      "char",
      "void",
      "return",
      "if",
      "else",
      "for",
      "while",
      "do",
      "switch",
      "case",
      "break",
      "continue",
      "using",
      "namespace",
      "class",
      "struct",
      "public",
      "private",
      "protected",
      "std",
      "cout",
      "cin",
      "endl",
      "vector",
      "string",
      "include",
      "new",
      "delete",
    ],
    c: [
      "int",
      "float",
      "double",
      "char",
      "void",
      "return",
      "if",
      "else",
      "for",
      "while",
      "do",
      "switch",
      "case",
      "break",
      "continue",
      "struct",
      "typedef",
      "NULL",
      "printf",
      "scanf",
      "malloc",
      "free",
      "include",
    ],
  };

  const langKw = kw[language] || [];
  if (langKw.length) {
    langKw.sort((a, b) => b.length - a.length);
    const regex = new RegExp(`\\b(${langKw.join("|")})\\b`, "g");
    text = text.replace(regex, (match) =>
      addPh(`<span class="text-[#c678dd] font-bold">${match}</span>`)
    ); // Keywords (Purple)
  }

  text = text.replace(/\b(\d+(?:\.\d+)?)\b/g, (match) =>
    addPh(`<span class="text-[#d19a66]">${match}</span>`)
  ); // Numbers (Orange)

  for (let i = 0; i < placeholders.length; i++) {
    text = text.replace(`__PH${i}__`, placeholders[i]);
  }
  return text;
};

// --- PREMIUM GLOBAL QUESTION FORMATTER ---
const renderQuestionContent = (text) => {
  if (!text) return null;
  const lines = text.split("\n");

  return lines.map((line, i) => {
    const headerMatch = line.match(/^\*\*(.*?)\*\*(.*)/);
    if (headerMatch) {
      return (
        <div key={i} className="mt-8 mb-4">
          <div className="flex items-center gap-2 mb-3">
            <div className="w-1.5 h-5 bg-blue-500 rounded-full shadow-[0_0_8px_rgba(59,130,246,0.6)]"></div>
            <h4 className="text-[13px] font-extrabold text-zinc-900 dark:text-white uppercase tracking-widest">
              {headerMatch[1]}
            </h4>
          </div>
          {headerMatch[2] && (
            <p className="text-[14px] text-zinc-600 dark:text-zinc-400 leading-relaxed bg-zinc-50 dark:bg-zinc-800/50 p-4 rounded-xl border border-zinc-100 dark:border-zinc-800/80">
              {headerMatch[2]}
            </p>
          )}
        </div>
      );
    }

    if (line.trim().startsWith("- ")) {
      const lineText = line.trim().substring(2);
      const codeParts = lineText.split(/(`.*?`)/g);
      return (
        <div key={i} className="flex items-start gap-2.5 mb-2.5 ml-2">
          <div className="w-1.5 h-1.5 rounded-full bg-blue-400 mt-2 flex-shrink-0"></div>
          <p className="text-[14px] text-zinc-700 dark:text-zinc-300 leading-relaxed">
            {codeParts.map((part, j) =>
              part.startsWith("`") && part.endsWith("`") ? (
                <code
                  key={j}
                  className="bg-zinc-100 dark:bg-zinc-800 text-blue-600 dark:text-blue-400 px-1.5 py-0.5 rounded font-mono text-[13px] border border-zinc-200 dark:border-zinc-700 shadow-sm mx-0.5"
                >
                  {part.slice(1, -1)}
                </code>
              ) : (
                part
              )
            )}
          </p>
        </div>
      );
    }

    if (line.trim() === "") return <div key={i} className="h-2"></div>;

    const codeParts = line.split(/(`.*?`)/g);
    return (
      <p
        key={i}
        className="mb-3 leading-relaxed text-[14px] text-zinc-700 dark:text-zinc-300 whitespace-pre-wrap"
      >
        {codeParts.map((part, j) =>
          part.startsWith("`") && part.endsWith("`") ? (
            <code
              key={j}
              className="bg-zinc-100 dark:bg-zinc-800 text-blue-600 dark:text-blue-400 px-1.5 py-0.5 rounded font-mono text-[13px] border border-zinc-200 dark:border-zinc-700 shadow-sm mx-0.5"
            >
              {part.slice(1, -1)}
            </code>
          ) : (
            part
          )
        )}
      </p>
    );
  });
};

// --- ALARM ENGINE ---
const playCheatAlarm = () => {
  try {
    const AudioContext = window.AudioContext || window.webkitAudioContext;
    if (!AudioContext) return;
    const ctx = new AudioContext();

    const playSiren = (freq1, freq2, startTime, duration) => {
      const osc1 = ctx.createOscillator();
      const osc2 = ctx.createOscillator();
      const gain = ctx.createGain();

      osc1.type = "square";
      osc2.type = "sawtooth";

      osc1.frequency.setValueAtTime(freq1, startTime);
      osc1.frequency.linearRampToValueAtTime(freq2, startTime + duration / 2);
      osc1.frequency.linearRampToValueAtTime(freq1, startTime + duration);

      osc2.frequency.setValueAtTime(freq1 * 1.5, startTime);
      osc2.frequency.linearRampToValueAtTime(
        freq2 * 1.5,
        startTime + duration / 2
      );
      osc2.frequency.linearRampToValueAtTime(freq1 * 1.5, startTime + duration);

      gain.gain.setValueAtTime(1.0, startTime);
      gain.gain.setValueAtTime(1.0, startTime + duration - 0.1);
      gain.gain.linearRampToValueAtTime(0.01, startTime + duration);

      osc1.connect(gain);
      osc2.connect(gain);
      gain.connect(ctx.destination);

      osc1.start(startTime);
      osc2.start(startTime);
      osc1.stop(startTime + duration);
      osc2.stop(startTime + duration);
    };

    const now = ctx.currentTime;
    for (let i = 0; i < 6; i++) {
      playSiren(1200, 2000, now + i * 0.4, 0.4);
    }
  } catch (e) {
    console.warn("Audio Context blocked.", e);
  }
};

// --- DRAGGABLE RESIZABLE GUI WINDOW COMPONENT ---
const DraggableGUIWindow = ({ title, html, onClose }) => {
  const [pos, setPos] = useState({
    x: Math.max(0, window.innerWidth / 2 - 250),
    y: Math.max(0, window.innerHeight / 2 - 200),
  });
  const [isDragging, setIsDragging] = useState(false);
  const [rel, setRel] = useState({ x: 0, y: 0 });
  const [isMinimized, setIsMinimized] = useState(false);

  const onMouseDown = (e) => {
    if (e.target.tagName === "BUTTON" || e.target.closest("button")) return;
    setIsDragging(true);
    setRel({
      x: e.pageX - pos.x,
      y: e.pageY - pos.y,
    });
    e.stopPropagation();
    e.preventDefault();
  };

  const onMouseUp = () => setIsDragging(false);

  const onMouseMove = (e) => {
    if (!isDragging) return;
    setPos({
      x: e.pageX - rel.x,
      y: e.pageY - rel.y,
    });
    e.stopPropagation();
    e.preventDefault();
  };

  useEffect(() => {
    if (isDragging) {
      document.addEventListener("mousemove", onMouseMove);
      document.addEventListener("mouseup", onMouseUp);
    } else {
      document.removeEventListener("mousemove", onMouseMove);
      document.removeEventListener("mouseup", onMouseUp);
    }
    return () => {
      document.removeEventListener("mousemove", onMouseMove);
      document.removeEventListener("mouseup", onMouseUp);
    };
  }, [isDragging, rel]);

  return (
    <div
      className={`fixed z-[300] flex flex-col bg-white dark:bg-zinc-900 border border-zinc-300 dark:border-zinc-700 rounded-lg shadow-2xl overflow-hidden transition-all ${
        isMinimized
          ? "w-64 h-12 resize-none"
          : "w-[90vw] sm:w-[500px] h-[60vh] sm:h-[400px] min-w-[300px] min-h-[200px]"
      }`}
      style={{
        left: pos.x,
        top: pos.y,
        resize: isMinimized ? "none" : "both",
        overflow: "hidden",
      }}
    >
      <div
        onMouseDown={onMouseDown}
        className="h-12 bg-zinc-100 dark:bg-zinc-800 flex items-center justify-between px-3 cursor-move border-b border-zinc-200 dark:border-zinc-700 flex-shrink-0"
      >
        <span className="font-bold text-sm text-zinc-800 dark:text-zinc-200 flex items-center gap-2">
          <AppWindow size={16} className="text-blue-500" /> {title}
        </span>
        <div className="flex gap-2">
          <button
            onClick={() => setIsMinimized(!isMinimized)}
            className="p-1 hover:bg-zinc-200 dark:hover:bg-zinc-700 rounded text-zinc-500 transition-colors"
          >
            {isMinimized ? <Maximize2 size={16} /> : <Minus size={16} />}
          </button>
          <button
            onClick={onClose}
            className="p-1 hover:bg-red-500 hover:text-white rounded text-zinc-500 transition-colors"
          >
            <X size={16} />
          </button>
        </div>
      </div>
      {!isMinimized && (
        <div className="flex-1 bg-white relative">
          {isDragging && (
            <div className="absolute inset-0 z-10 cursor-move"></div>
          )}
          <iframe
            title="GUI Preview"
            srcDoc={html}
            sandbox="allow-scripts allow-same-origin"
            className="w-full h-full border-none"
          />
        </div>
      )}
    </div>
  );
};

// --- MAIN APP COMPONENT ---
export default function App() {
  const [user, setUser] = useState(null);
  const [userData, setUserData] = useState(null);
  const [view, setView] = useState("login");
  const [selectedLanguage, setSelectedLanguage] = useState("python");
  const [globalMessage, setGlobalMessage] = useState({ text: "", type: "" });

  const [isDarkMode, setIsDarkMode] = useState(() => {
    try {
      const saved = window.localStorage.getItem("app_theme");
      if (saved) return saved === "dark";
      if (typeof window !== "undefined" && window.matchMedia) {
        return window.matchMedia("(prefers-color-scheme: dark)").matches;
      }
    } catch (e) {
      console.warn("Theme storage access denied.");
    }
    return true;
  });

  useEffect(() => {
    try {
      window.localStorage.setItem("app_theme", isDarkMode ? "dark" : "light");
    } catch (e) {}

    const root = document.documentElement;
    if (isDarkMode) {
      root.classList.add("dark");
      root.style.colorScheme = "dark";
    } else {
      root.classList.remove("dark");
      root.style.colorScheme = "light";
    }
  }, [isDarkMode]);

  // --- GLOBAL ANTI-INSPECT SECURITY ---
  useEffect(() => {
    const blockShortcuts = (e) => {
      if (
        e.key === "F12" ||
        (e.ctrlKey &&
          e.shiftKey &&
          (e.key === "I" ||
            e.key === "J" ||
            e.key === "C" ||
            e.key === "i" ||
            e.key === "j" ||
            e.key === "c")) ||
        (e.ctrlKey && (e.key === "U" || e.key === "u")) ||
        (e.metaKey &&
          e.altKey &&
          (e.key === "I" ||
            e.key === "J" ||
            e.key === "U" ||
            e.key === "i" ||
            e.key === "j" ||
            e.key === "u"))
      ) {
        e.preventDefault();
        showMessage("Security Alert: Developer tools are disabled.", "error");
      }
    };

    const blockContextMenu = (e) => {
      e.preventDefault();
      showMessage("Security Alert: Right-click is disabled.", "error");
    };

    const debuggerTrap = setInterval(() => {
      const before = new Date().getTime();
      // eslint-disable-next-line no-debugger
      debugger;
      const after = new Date().getTime();
    }, 100);

    document.addEventListener("keydown", blockShortcuts);
    document.addEventListener("contextmenu", blockContextMenu);

    return () => {
      document.removeEventListener("keydown", blockShortcuts);
      document.removeEventListener("contextmenu", blockContextMenu);
      clearInterval(debuggerTrap);
    };
  }, []);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (currentUser) => {
      setUser(currentUser);
      if (currentUser) {
        try {
          const unsubDoc = onSnapshot(
            doc(db, "users", currentUser.uid),
            (docSnap) => {
              if (docSnap.exists()) {
                const data = docSnap.data();
                setUserData(data);
                if (data.selectedLanguage)
                  setSelectedLanguage(data.selectedLanguage);
                setView((prevView) => {
                  if (data.role === "admin" && prevView === "login")
                    return "admin";
                  if (!data.isVerified && data.role !== "admin")
                    return "verify";
                  if (
                    data.isVerified &&
                    data.role !== "admin" &&
                    (prevView === "login" || prevView === "verify")
                  ) {
                    return data.selectedLanguage ? "quiz" : "language-select";
                  }
                  return prevView;
                });
              }
            }
          );
          return () => unsubDoc();
        } catch (e) {
          console.error("Error fetching user data:", e);
        }
      } else {
        setView("login");
      }
    });
    return () => unsubscribe();
  }, []);

  const showMessage = (text, type = "info") => {
    setGlobalMessage({ text, type });
    setTimeout(() => setGlobalMessage({ text: "", type: "" }), 4000);
  };

  const handleLogout = async () => {
    await auth.signOut();
    setUserData(null);
    setView("login");
  };

  return (
    <div className="h-screen w-full bg-[#f4f4f5] dark:bg-[#09090b] text-zinc-900 dark:text-zinc-300 font-sans flex flex-col selection:bg-zinc-300 dark:selection:bg-zinc-700 overflow-hidden transition-colors duration-300">
      {globalMessage.text && (
