      {user && userData && (
        <nav className="h-16 flex-shrink-0 border-b border-zinc-200 dark:border-zinc-800/50 bg-white/80 dark:bg-[#09090b]/80 backdrop-blur-xl flex items-center justify-between px-4 sm:px-6 shadow-sm z-40">
          <div className="flex items-center gap-2 text-zinc-800 dark:text-zinc-100 font-bold text-lg sm:text-xl tracking-tight">
            <div className="bg-zinc-900 dark:bg-white text-white dark:text-zinc-900 p-1.5 rounded-lg">
              <Code2 size={20} />
            </div>
            <span className="hidden sm:inline">CSJMU</span>
            <span className="hidden sm:inline font-medium">Coding</span>
