// --- MINIMALIST BENTO LOGIN ---
function LoginView({ setUserData, showMessage, setView }) {
  const [isRegister, setIsRegister] = useState(false);
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [username, setUsername] = useState("");
  const [isAdminLogin, setIsAdminLogin] = useState(false);
  const [adminPassword, setAdminPassword] = useState("");
  const [loading, setLoading] = useState(false);

  const handleAuth = async (e) => {
    e.preventDefault();
    const safeEmail = email.trim();
    const safePassword = password.trim();

    if (!safeEmail || !safePassword)
      return showMessage("Credentials required.", "error");
    if (isRegister && safePassword.length < 6)
      return showMessage("Password must be at least 6 characters.", "error");

    setLoading(true);
    try {
      if (isRegister) {
        if (!username.trim()) {
          setLoading(false);
          return showMessage("Please provide a username.", "error");
        }
        if (isAdminLogin && adminPassword !== "admin") {
          setLoading(false);
          return showMessage("Incorrect admin password.", "error");
        }

        const userCredential = await createUserWithEmailAndPassword(
          auth,
          safeEmail,
          safePassword
        );
        const user = userCredential.user;
        const role = isAdminLogin ? "admin" : "student";
        const userDataObj = {
          uid: user.uid,
          username: username.trim(),
          email: email.trim(),
          role: role,
          score: 0,
          tabSwitches: 0,
          cheatLogs: [],
          isVerified: role === "admin",
          accessKey: null,
          testDurationMinutes: 90,
          testStartTime: null,
          completionTime: null,
          lockedUntil: null,
          currentQuestionIndex: 0,
          selectedLanguage: null,
          createdAt: serverTimestamp(),
        };

        await setDoc(doc(db, "users", user.uid), userDataObj);
        setUserData(userDataObj);
        setView(role === "admin" ? "admin" : "verify");
        showMessage(`Account created. Welcome, ${username}.`, "success");
      } else {
        if (isAdminLogin && adminPassword !== "admin") {
          setLoading(false);
          return showMessage("Incorrect admin password.", "error");
        }

        const userCredential = await signInWithEmailAndPassword(
          auth,
          safeEmail,
          safePassword
        );
        const user = userCredential.user;
        const docSnap = await getDoc(doc(db, "users", user.uid));

        if (docSnap.exists()) {
          const data = docSnap.data();
          if (isAdminLogin && data.role !== "admin") {
            await auth.signOut();
            setLoading(false);
            return showMessage("You do not have admin privileges.", "error");
          }
          setUserData(data);
          if (data.role === "admin") setView("admin");
          else if (!data.isVerified) setView("verify");
          else if (data.selectedLanguage) setView("quiz");
          else setView("language-select");

          showMessage(`Welcome back, ${data.username}.`, "success");
        } else {
          showMessage("User profile missing. Please contact admin.", "error");
        }
      }
    } catch (error) {
      let errorMessage = "Access denied.";
      if (error.code === "auth/email-already-in-use") {
        errorMessage = "Email registered. Switching to Log In.";
        setIsRegister(false);
      } else if (
        error.code === "auth/invalid-credential" ||
        error.code === "auth/wrong-password"
      ) {
        errorMessage = "Invalid email or password.";
      } else if (error.code === "auth/user-not-found") {
        errorMessage = "No account found. Please sign up first.";
      }
      showMessage(errorMessage, "error");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="flex-1 w-full h-full overflow-y-auto custom-scrollbar">
      <div className="min-h-full flex items-center justify-center p-4 sm:p-8">
        <div className="w-full max-w-4xl grid grid-cols-1 md:grid-cols-2 gap-6 bg-white dark:bg-[#0f0f11] p-2 rounded-[2rem] shadow-xl border border-zinc-200 dark:border-zinc-800/50">
          <div className="bg-zinc-50 dark:bg-[#18181b] rounded-[1.5rem] p-8 sm:p-12 flex flex-col justify-between items-start border border-zinc-100 dark:border-zinc-800/50 relative overflow-hidden">
            <div className="absolute -top-24 -left-24 w-64 h-64 bg-zinc-200 dark:bg-zinc-800 rounded-full blur-[80px] opacity-50"></div>
            <div className="relative z-10 w-full">
              <div
                className="bg-zinc-900 dark:bg-zinc-100 text-white dark:text-zinc-900 w-16 h-16 rounded-2xl flex items-center justify-center mb-8 cursor-default shadow-sm"
                onDoubleClick={() => {
                  setIsAdminLogin(!isAdminLogin);
                  showMessage(
                    isAdminLogin ? "Student Mode" : "Admin Mode Unlocked",
                    "info"
                  );
                }}
              >
                <Code2 size={32} />
              </div>
              <h1 className="text-4xl font-extrabold text-zinc-900 dark:text-zinc-100 tracking-tight leading-tight mb-4">
                CSJMU
                <br />
                <span className="text-zinc-500 dark:text-zinc-400 font-medium text-2xl md:text-3xl">
                  Coding Competition
                </span>
              </h1>
              <p className="text-zinc-500 dark:text-zinc-400 text-sm leading-relaxed max-w-[250px]">
                A secure, minimalist environment for technical evaluations.
              </p>
            </div>
            <div className="relative z-10 mt-12 w-full">
              <div className="flex items-center gap-3 text-xs font-bold text-zinc-400 uppercase tracking-widest">
                <span className="w-8 h-px bg-zinc-300 dark:bg-zinc-700"></span>{" "}
                Environment Ready
              </div>
            </div>
          </div>

          <div className="p-8 sm:p-12 flex flex-col justify-center">
            <h2 className="text-2xl font-bold text-zinc-900 dark:text-zinc-100 mb-2">
              {isRegister ? "Create Account" : "Welcome Back"}
            </h2>
            <p className="text-sm text-zinc-500 dark:text-zinc-400 mb-8">
              {isRegister
                ? "Enter your details to begin the exam."
                : "Enter your credentials to continue."}
            </p>

            <form onSubmit={handleAuth} className="space-y-5">
              {isRegister && (
                <div className="animate-in fade-in slide-in-from-top-2">
                  <label className="block text-[11px] font-bold text-zinc-500 dark:text-zinc-400 mb-2 uppercase tracking-widest">
                    Username
                  </label>
                  <input
                    type="text"
                    value={username}
                    onChange={(e) => setUsername(e.target.value)}
                    className="w-full bg-zinc-50 dark:bg-[#18181b] border border-zinc-200 dark:border-zinc-800 rounded-xl px-4 py-3.5 text-zinc-900 dark:text-zinc-100 text-sm focus:outline-none focus:ring-2 focus:ring-zinc-200 dark:focus:ring-zinc-700 transition-all placeholder-zinc-400 dark:placeholder-zinc-600"
                    placeholder="johndoe"
                    required={isRegister}
                  />
                </div>
              )}
              <div>
                <label className="block text-[11px] font-bold text-zinc-500 dark:text-zinc-400 mb-2 uppercase tracking-widest">
                  Email
                </label>
                <input
                  type="email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  className="w-full bg-zinc-50 dark:bg-[#18181b] border border-zinc-200 dark:border-zinc-800 rounded-xl px-4 py-3.5 text-zinc-900 dark:text-zinc-100 text-sm focus:outline-none focus:ring-2 focus:ring-zinc-200 dark:focus:ring-zinc-700 transition-all placeholder-zinc-400 dark:placeholder-zinc-600"
                  placeholder="student@university.edu"
                  required
                />
              </div>
              <div>
                <label className="block text-[11px] font-bold text-zinc-500 dark:text-zinc-400 mb-2 uppercase tracking-widest">
                  Password
                </label>
                <input
                  type="password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="w-full bg-zinc-50 dark:bg-[#18181b] border border-zinc-200 dark:border-zinc-800 rounded-xl px-4 py-3.5 text-zinc-900 dark:text-zinc-100 text-sm focus:outline-none focus:ring-2 focus:ring-zinc-200 dark:focus:ring-zinc-700 transition-all placeholder-zinc-400 dark:placeholder-zinc-600"
                  placeholder="••••••••"
                  required
                  minLength={6}
                />
              </div>

              {isAdminLogin && (
                <div className="animate-in fade-in slide-in-from-top-2 pt-2">
                  <label className="block text-[11px] font-bold text-zinc-900 dark:text-white mb-2 uppercase tracking-widest">
                    Admin Authorization
                  </label>
                  <input
                    type="password"
                    value={adminPassword}
                    onChange={(e) => setAdminPassword(e.target.value)}
                    className="w-full bg-zinc-100 dark:bg-zinc-800 border border-zinc-300 dark:border-zinc-600 rounded-xl px-4 py-3.5 text-zinc-900 dark:text-zinc-100 text-sm focus:outline-none focus:ring-2 focus:ring-zinc-400 dark:focus:ring-zinc-500 transition-all"
                    placeholder="Secret Key"
                    required={isAdminLogin}
                  />
                </div>
              )}

              <button
                type="submit"
                disabled={loading}
                className="w-full bg-zinc-900 hover:bg-zinc-800 dark:bg-zinc-100 dark:hover:bg-white text-white dark:text-zinc-900 rounded-xl px-4 py-3.5 font-bold text-sm transition-all flex items-center justify-center gap-2 mt-2 disabled:opacity-50"
              >
                {loading ? (
                  <Loader2 size={16} className="animate-spin" />
                ) : null}
                {loading
                  ? "Authenticating..."
                  : isRegister
                  ? "Create Account"
                  : "Sign In"}
              </button>
            </form>

            <div className="mt-8">
              <p className="text-xs text-zinc-500 dark:text-zinc-400">
                {isRegister ? "Already evaluated? " : "First time here? "}
                <button
                  onClick={() => setIsRegister(!isRegister)}
                  className="text-zinc-900 dark:text-zinc-100 font-bold hover:underline transition-colors"
                >
                  {isRegister ? "Sign In" : "Register"}
                </button>
              </p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

// --- VERIFICATION (KEY) VIEW ---
function VerifyView({ user, userData, setView, showMessage, setUserData }) {
  const [inputKey, setInputKey] = useState("");
  const [loading, setLoading] = useState(false);

  const handleVerify = async (e) => {
    e.preventDefault();
    setLoading(true);
    try {
      const userDoc = await getDoc(doc(db, "users", user.uid));
      const liveData = userDoc.data();
      if (liveData.accessKey && inputKey.trim() === liveData.accessKey) {
        await updateDoc(doc(db, "users", user.uid), { isVerified: true });
        setUserData({ ...liveData, isVerified: true });
        if (liveData.selectedLanguage) setView("quiz");
        else setView("language-select");
      } else {
        showMessage("Invalid access key.", "error");
      }
    } catch (err) {
      showMessage("Error verifying key.", "error");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="flex-1 flex items-center justify-center p-6">
      <div className="w-full max-w-sm bg-white dark:bg-[#18181b] border border-zinc-200 dark:border-zinc-800 rounded-[2rem] p-10 shadow-sm text-center">
        <div className="flex justify-center mb-6">
          <div className="p-4 bg-zinc-100 dark:bg-zinc-900 rounded-2xl border border-zinc-200 dark:border-zinc-800">
            <Key size={32} className="text-zinc-900 dark:text-zinc-100" />
          </div>
        </div>
        <h2 className="text-xl font-bold text-zinc-900 dark:text-zinc-100 mb-2">
          Workspace Locked
        </h2>
        <p className="text-zinc-500 dark:text-zinc-400 mb-8 text-sm leading-relaxed">
          Provide your unique invigilator access key to enter the secure
          environment.
        </p>
        <form onSubmit={handleVerify} className="space-y-4">
          <input
            type="text"
            value={inputKey}
            onChange={(e) => setInputKey(e.target.value.toUpperCase())}
            className="w-full bg-zinc-50 dark:bg-[#0f0f11] border border-zinc-200 dark:border-zinc-800 rounded-xl px-4 py-4 text-center text-xl tracking-[0.3em] text-zinc-900 dark:text-zinc-100 font-mono focus:outline-none focus:border-zinc-400 dark:focus:border-zinc-600 transition-colors placeholder-zinc-300 dark:placeholder-zinc-700"
            placeholder="ENTER KEY"
            required
          />
          <button
            type="submit"
            disabled={loading}
            className="w-full bg-zinc-900 dark:bg-zinc-100 text-white dark:text-zinc-900 rounded-xl px-4 py-4 font-bold text-sm transition-all flex items-center justify-center gap-2"
          >
            {loading ? (
              <Loader2 size={16} className="animate-spin" />
            ) : (
              "Unlock Workspace"
            )}
          </button>
        </form>
      </div>
    </div>
  );
}

