                {lang.icon}
              </div>
              <div className="flex flex-col items-center gap-1.5">
                <span className="text-base font-bold text-zinc-900 dark:text-zinc-100 group-hover:text-blue-600 dark:group-hover:text-blue-400 transition-colors">
                  {lang.name}
                </span>
              </div>
            </button>
          ))}
        </div>
      </div>
    </div>
  );
}

// --- STRICT IDE WORKSPACE VIEW ---
function QuizView({ user, userData, showMessage, selectedLanguage }) {
  const [questions, setQuestions] = useState([]);
  const [code, setCode] = useState("");

  const [terminalTab, setTerminalTab] = useState("bash"); // 'bash' or 'input'

  const [testCases, setTestCases] = useState([
    {
      id: 1,
      input: "",
      expectedOutput: "",
      actualOutput: null,
      status: "idle",
    },
  ]);
  const [activeTestCaseId, setActiveTestCaseId] = useState(1);
  const [isRunningTests, setIsRunningTests] = useState(false);

  const [terminalHistory, setTerminalHistory] = useState([]);
  const [isWaitingForInput, setIsWaitingForInput] = useState(false);
  const [terminalInputValue, setTerminalInputValue] = useState("");
  const [cmdHistory, setCmdHistory] = useState([]);
  const [cmdIndex, setCmdIndex] = useState(-1);
  const [isTerminalVisible, setIsTerminalVisible] = useState(true);
  const [isTerminalMaximized, setIsTerminalMaximized] = useState(false);
  const [isQuestionVisible, setIsQuestionVisible] = useState(true);
  const [guiPreviewHtml, setGuiPreviewHtml] = useState(null);

  const [isRunning, setIsRunning] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [fetchingQuestions, setFetchingQuestions] = useState(true);

  const [timeLeftStr, setTimeLeftStr] = useState("");
  const [timeExpired, setTimeExpired] = useState(false);
  const [penaltyLockTimeStr, setPenaltyLockTimeStr] = useState("");

  const [activeLine, setActiveLine] = useState(1);
  const [errorLine, setErrorLine] = useState(null);
  const [cursorPos, setCursorPos] = useState({ line: 1, col: 1 });
  const [fontSize, setFontSize] = useState(14);
  const [copied, setCopied] = useState(false);

  const editorRef = useRef(null);
  const highlightRef = useRef(null);
  const lineNumbersRef = useRef(null);
  const terminalBottomRef = useRef(null);
  const terminalInputRef = useRef(null);

  const defaultCode = {
    python:
      'def solve():\n    # WRITE YOUR CODE HERE\n    pass\n\nif __name__ == "__main__":\n    solve()',
    java: "import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        // WRITE YOUR CODE HERE\n    }\n}",
    "c++":
      "#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    // WRITE YOUR CODE HERE\n    return 0;\n}",
    c: "#include <stdio.h>\n#include <stdlib.h>\n\nint main() {\n    // WRITE YOUR CODE HERE\n    return 0;\n}",
  };

  const currentIndex = userData?.currentQuestionIndex || 0;
  const activeQuestion = questions[currentIndex] || null;

  useEffect(() => {
    const q = query(collection(db, "questions"), orderBy("createdAt", "asc"));
    const unsubscribe = onSnapshot(q, (snapshot) => {
      const allQs = snapshot.docs.map((doc) => ({ id: doc.id, ...doc.data() }));
      let filteredQs = allQs.filter((q) => q.language === selectedLanguage);

      if (user?.uid) {
        const getHash = (str) => {
          let hash = 0;
          for (let i = 0; i < str.length; i++) {
            hash = (hash << 5) - hash + str.charCodeAt(i);
            hash |= 0;
          }
          return hash;
        };
        filteredQs.sort(
          (a, b) => getHash(user.uid + a.id) - getHash(user.uid + b.id)
        );
      }

      setQuestions(filteredQs);
      setFetchingQuestions(false);
    });
    return () => unsubscribe();
  }, [selectedLanguage, user]);

  useEffect(() => {
    if (activeQuestion && selectedLanguage && user?.uid) {
      const fetchDraft = async () => {
        const draftKey = `draft_code_${user.uid}_${activeQuestion.id}`;
        const localDraft = localStorage.getItem(draftKey);

        if (localDraft) {
          setCode(localDraft);
        } else {
          try {
            const docRef = doc(
              db,
              "users",
              user.uid,
              "drafts",
              activeQuestion.id
            );
            const docSnap = await getDoc(docRef);
            if (docSnap.exists() && docSnap.data().code) {
              const saved = docSnap.data().code;
              setCode(saved);
              localStorage.setItem(draftKey, saved);
            } else {
              setCode(defaultCode[selectedLanguage] || "");
            }
          } catch (e) {
            setCode(defaultCode[selectedLanguage] || "");
          }
        }
      };
      fetchDraft();
      setTerminalHistory([]);
      setGuiPreviewHtml(null);
      setErrorLine(null);

      setTestCases([
        {
          id: 1,
          input: activeQuestion.expectedInput || "",
          expectedOutput: activeQuestion.expectedOutput || "",
          actualOutput: null,
          status: "idle",
        },
      ]);
      setActiveTestCaseId(1);
    }
  }, [selectedLanguage, activeQuestion?.id, user?.uid]);

  useEffect(() => {
    const timer = setTimeout(() => {
      if (
        code &&
        user?.uid &&
        activeQuestion?.id &&
        code !== defaultCode[selectedLanguage]
      ) {
        setDoc(
          doc(db, "users", user.uid, "drafts", activeQuestion.id),
          {
            code,
            timestamp: serverTimestamp(),
          },
          { merge: true }
        ).catch((e) => console.log("Silent cloud save error", e));
      }
    }, 5000);
    return () => clearTimeout(timer);
  }, [code, user?.uid, activeQuestion?.id, selectedLanguage]);

  useEffect(() => {
    if (terminalBottomRef.current) {
      terminalBottomRef.current.scrollIntoView({ behavior: "smooth" });
    }
  }, [terminalHistory, isWaitingForInput]);

  const handleStartTest = async () => {
    try {
      await updateDoc(doc(db, "users", user.uid), {
        testStartTime: serverTimestamp(),
      });
    } catch (err) {
      showMessage("Failed to start test.", "error");
    }
  };

  useEffect(() => {
    if (!userData) return;
    const interval = setInterval(() => {
      const now = Date.now();

      if (userData.testStartTime) {
        let startMs = userData.testStartTime.toMillis
          ? userData.testStartTime.toMillis()
          : now;
        const durationMs = (userData.testDurationMinutes || 90) * 60 * 1000;
        const remainingMs = Math.max(0, durationMs - (now - startMs));

        if (remainingMs === 0) {
          setTimeExpired(true);
          setTimeLeftStr("00:00:00");
        } else {
          setTimeExpired(false);
          const h = Math.floor(remainingMs / (1000 * 60 * 60));
          const m = Math.floor((remainingMs % (1000 * 60 * 60)) / (1000 * 60));
          const s = Math.floor((remainingMs % (1000 * 60)) / 1000);
          setTimeLeftStr(
            `${h.toString().padStart(2, "0")}:${m
              .toString()
              .padStart(2, "0")}:${s.toString().padStart(2, "0")}`
          );
        }
      }

      if (userData.lockedUntil && userData.lockedUntil > now) {
        const lockMins = Math.floor((userData.lockedUntil - now) / 60000);
        const lockSecs = Math.floor(
          ((userData.lockedUntil - now) % 60000) / 1000
        );
        setPenaltyLockTimeStr(
          `${lockMins}:${lockSecs.toString().padStart(2, "0")}`
        );
      } else {
        setPenaltyLockTimeStr("");
      }
    }, 1000);
    return () => clearInterval(interval);
  }, [userData]);

  useEffect(() => {
    const blockShortcuts = (e) => {
      if (
        e.key === "F12" ||
        (e.ctrlKey &&
          e.shiftKey &&
          (e.key === "I" || e.key === "J" || e.key === "C")) ||
        (e.ctrlKey && e.key === "U")
      ) {
        e.preventDefault();
        showMessage("Security Alert: Developer tools are disabled.", "error");
      }
    };

    const blockContextMenu = (e) => {
      e.preventDefault();
      showMessage("Security Alert: Right-click is disabled.", "error");
    };

    const debuggerTrap = setInterval(() => {
      const before = new Date().getTime();
      // eslint-disable-next-line no-debugger
      debugger;
      const after = new Date().getTime();
    }, 100);

    const handleVisibilityChange = async () => {
      const isTestComplete =
        currentIndex >= questions.length && questions.length > 0;

      if (
        document.visibilityState === "hidden" &&
        user &&
        userData?.testStartTime &&
        !timeExpired &&
        !isTestComplete
      ) {
        try {
          playCheatAlarm();
          const timestampStr = new Date().toLocaleTimeString([], {
            hour: "2-digit",
            minute: "2-digit",
            second: "2-digit",
          });
          await updateDoc(doc(db, "users", user.uid), {
            tabSwitches: increment(1),
            cheatLogs: arrayUnion({
              time: timestampStr,
              type: "Focus Lost / Switched Tab",
            }),
          });
          document.title = "⚠️ Return to Test!";
        } catch (e) {}
      } else {
        document.title = "CSJMU Coding";
      }
    };

    document.addEventListener("visibilitychange", handleVisibilityChange);
    window.addEventListener("blur", handleVisibilityChange);
    document.addEventListener("keydown", blockShortcuts);
    document.addEventListener("contextmenu", blockContextMenu);

    return () => {
      document.removeEventListener("visibilitychange", handleVisibilityChange);
      window.removeEventListener("blur", handleVisibilityChange);
      document.removeEventListener("keydown", blockShortcuts);
      document.removeEventListener("contextmenu", blockContextMenu);
      clearInterval(debuggerTrap);
    };
  }, [user, userData, timeExpired, questions, currentIndex]);

  const updateActiveLine = () => {
    if (!editorRef.current) return;
    const val = editorRef.current.value;
    const pos = editorRef.current.selectionStart;
    const linesBefore = val.substring(0, pos).split("\n");
    setActiveLine(linesBefore.length);
    setCursorPos({
      line: linesBefore.length,
      col: linesBefore[linesBefore.length - 1].length + 1,
    });
  };

  const handleEditorChange = (e) => {
    const newCode = e.target.value;
    setCode(newCode);
    updateActiveLine();
    if (errorLine) setErrorLine(null);

    if (activeQuestion && user?.uid) {
      localStorage.setItem(
        `draft_code_${user.uid}_${activeQuestion.id}`,
        newCode
      );
    }
  };

  const handleEditorKeyDown = (e) => {
    if (penaltyLockTimeStr) return;

    if ((e.ctrlKey || e.metaKey) && e.key === "Enter") {
      e.preventDefault();
      runCodeInteractive();
      return;
    }

    const textarea = editorRef.current;
    const start = textarea.selectionStart;
    const end = textarea.selectionEnd;
    const val = textarea.value;

    if (e.key === "Tab") {
      e.preventDefault();
      if (e.shiftKey) {
        const lineStart = val.lastIndexOf("\n", start - 1) + 1;
        if (val.substring(lineStart, lineStart + 4) === "    ") {
          const updated =
            val.substring(0, lineStart) + val.substring(lineStart + 4);
          setCode(updated);
          if (activeQuestion && user?.uid)
            localStorage.setItem(
              `draft_code_${user.uid}_${activeQuestion.id}`,
              updated
            );
          setTimeout(() => {
            textarea.selectionStart = textarea.selectionEnd = start - 4;
          }, 0);
        }
      } else {
        const updated = val.substring(0, start) + "    " + val.substring(end);
        setCode(updated);
        if (activeQuestion && user?.uid)
          localStorage.setItem(
            `draft_code_${user.uid}_${activeQuestion.id}`,
            updated
          );
        setTimeout(() => {
          textarea.selectionStart = textarea.selectionEnd = start + 4;
        }, 0);
      }
    }

    if (e.key === "Enter") {
      e.preventDefault();
      const lines = val.substring(0, start).split("\n");
      const lastLine = lines[lines.length - 1];
      const match = lastLine.match(/^\s*/);
      let indent = match ? match[0] : "";

      const charBefore = val.charAt(start - 1);
      const charAfter = val.charAt(start);

      if (
        (charBefore === "{" && charAfter === "}") ||
        (charBefore === "[" && charAfter === "]") ||
        (charBefore === "(" && charAfter === ")")
      ) {
        const updated =
          val.substring(0, start) +
          "\n" +
          indent +
          "    " +
          "\n" +
          indent +
          val.substring(end);
        setCode(updated);
        if (activeQuestion && user?.uid)
          localStorage.setItem(
            `draft_code_${user.uid}_${activeQuestion.id}`,
            updated
          );
        setTimeout(() => {
          textarea.selectionStart = textarea.selectionEnd =
            start + 1 + indent.length + 4;
          updateActiveLine();
        }, 0);
      } else {
        if (charBefore === ":" || charBefore === "{" || charBefore === "[") {
          indent += "    ";
        }
        const updated =
          val.substring(0, start) + "\n" + indent + val.substring(end);
        setCode(updated);
        if (activeQuestion && user?.uid)
          localStorage.setItem(
            `draft_code_${user.uid}_${activeQuestion.id}`,
            updated
          );
        setTimeout(() => {
          textarea.selectionStart = textarea.selectionEnd =
            start + 1 + indent.length;
          updateActiveLine();
        }, 0);
      }
    }

    const bracketPairs = { "(": ")", "{": "}", "[": "]", '"': '"', "'": "'" };
    if (bracketPairs[e.key]) {
      e.preventDefault();
      if (start !== end) {
        const selectedText = val.substring(start, end);
        const updated =
          val.substring(0, start) +
          e.key +
          selectedText +
          bracketPairs[e.key] +
          val.substring(end);
        setCode(updated);
        setTimeout(() => {
          textarea.selectionStart = start + 1;
          textarea.selectionEnd = end + 1;
        }, 0);
      } else {
        const updated =
          val.substring(0, start) +
          e.key +
          bracketPairs[e.key] +
          val.substring(end);
        setCode(updated);
        if (activeQuestion && user?.uid)
          localStorage.setItem(
            `draft_code_${user.uid}_${activeQuestion.id}`,
            updated
          );
        setTimeout(() => {
          textarea.selectionStart = textarea.selectionEnd = start + 1;
          updateActiveLine();
        }, 0);
      }
    }

    if (
      e.key === ")" ||
      e.key === "}" ||
      e.key === "]" ||
      e.key === '"' ||
      e.key === "'"
    ) {
      if (val.charAt(start) === e.key) {
        e.preventDefault();
        setTimeout(() => {
          textarea.selectionStart = textarea.selectionEnd = start + 1;
        }, 0);
      }
    }
  };

  const handleScroll = (e) => {
    if (highlightRef.current) {
      highlightRef.current.scrollTop = e.target.scrollTop;
      highlightRef.current.scrollLeft = e.target.scrollLeft;
    }
    if (lineNumbersRef.current)
      lineNumbersRef.current.scrollTop = e.target.scrollTop;
  };

  const getTimeStamp = () => {
    const d = new Date();
    return `[${d.getHours().toString().padStart(2, "0")}:${d
      .getMinutes()
      .toString()
      .padStart(2, "0")}:${d.getSeconds().toString().padStart(2, "0")}]`;
  };

  const parseErrorLine = (output, lang) => {
    let match = null;
    if (lang === "python") {
      match = output.match(/line\s+(\d+)/i);
    } else if (lang === "java") {
      match = output.match(/\.java:(\d+)/i) || output.match(/line\s+(\d+)/i);
    } else if (lang === "c++" || lang === "c") {
      match =
        output.match(/\.c(?:pp)?:(\d+)/i) || output.match(/line\s+(\d+)/i);
    } else {
      match = output.match(/line\s+(\d+)/i);
    }

    if (match && match[1]) {
      return parseInt(match[1]);
    }
    return null;
  };

  const resetEditorCode = () => {
    const template = defaultCode[selectedLanguage] || "";
    setCode(template);
    if (activeQuestion && user?.uid) {
      localStorage.setItem(
        `draft_code_${user.uid}_${activeQuestion.id}`,
        template
      );
    }
    showMessage("Code reset to language default.", "info");
  };

  const updateTestCase = (id, field, value) => {
    setTestCases((prev) =>
      prev.map((tc) =>
        tc.id === id
          ? { ...tc, [field]: value, status: "idle", actualOutput: null }
          : tc
      )
    );
  };

  const addTestCase = () => {
    const newId = testCases.length
      ? Math.max(...testCases.map((t) => t.id)) + 1
      : 1;
    setTestCases([
      ...testCases,
      {
        id: newId,
        input: "",
        expectedOutput: "",
        actualOutput: null,
        status: "idle",
      },
    ]);
    setActiveTestCaseId(newId);
  };

  const removeTestCase = (id, e) => {
    e.stopPropagation();
    if (testCases.length === 1) return;
    const newCases = testCases.filter((tc) => tc.id !== id);
    setTestCases(newCases);
    if (activeTestCaseId === id) setActiveTestCaseId(newCases[0].id);
  };

  const runAllTestCases = async () => {
    if (penaltyLockTimeStr) return;
    setIsRunningTests(true);
    setTerminalTab("input");
    setIsTerminalVisible(true);
    setGuiPreviewHtml(null);
    setErrorLine(null);

    let currentTestCases = [...testCases].map((tc) => ({
      ...tc,
      status: "running",
      actualOutput: null,
    }));
    setTestCases(currentTestCases);

    for (let i = 0; i < currentTestCases.length; i++) {
      const tc = currentTestCases[i];
      const prompt = `You are a raw terminal environment. Execute this ${selectedLanguage} code using the provided standard input.
            Code:
            ${code}

            Standard Input:
            ${tc.input}

            CRITICAL TERMINAL RULES:
            1. Run the code from start to finish using the provided Standard Input.
            2. Output ONLY the exact standard output produced by the code. 
            3. ABSOLUTELY NO CONVERSATION. Do not say "Here is the output" or explain the code. Output nothing but the raw terminal text.
            4. NO MARKDOWN. Do not wrap the output in \`\`\` blocks.
            5. COMPILER ERRORS: Prefix with exactly [ERROR] followed by the raw stack trace.
            6. If the code produces no output, return an empty string.`;

      try {
        const result = await callGroq(prompt);
        let cleanedResult = result
          .replace(/```[a-zA-Z]*\n?/g, "")
          .replace(/```/g, "")
          .trimStart();

        let isErrorOutput = false;
        if (cleanedResult.startsWith("[ERROR]")) {
          isErrorOutput = true;
          cleanedResult = cleanedResult.replace("[ERROR]", "").trim();
          const errLine = parseErrorLine(cleanedResult, selectedLanguage);
          if (errLine) setErrorLine(errLine);
        }

        let passed = false;
        if (!isErrorOutput && tc.expectedOutput) {
          const normActual = cleanedResult.replace(/\r\n/g, "\n").trim();
          const normExpected = tc.expectedOutput.replace(/\r\n/g, "\n").trim();
          passed = normActual === normExpected;
        } else if (!isErrorOutput && !tc.expectedOutput) {
          passed = true;
        }

        currentTestCases[i] = {
          ...tc,
          actualOutput: cleanedResult,
          status: isErrorOutput ? "error" : passed ? "passed" : "failed",
        };

        setTestCases([...currentTestCases]);
      } catch (err) {
        currentTestCases[i] = {
          ...tc,
          actualOutput: err.message,
          status: "error",
        };
        setTestCases([...currentTestCases]);
      }
    }
    setIsRunningTests(false);
  };

  const handleTopTestCaseRun = () => {
    setTerminalTab("input");
    setIsTerminalVisible(true);
    runAllTestCases();
  };

  const runCodeInteractive = async () => {
    if (penaltyLockTimeStr) return;
    setIsTerminalVisible(true);
    setTerminalTab("bash");
    setIsRunning(true);
    setIsWaitingForInput(false);
    setGuiPreviewHtml(null);
    setErrorLine(null);

    const startCmd =
      selectedLanguage === "python"
        ? "python main.py"
        : selectedLanguage === "java"
        ? "javac Main.java && java Main"
        : "gcc main.c && ./a.out";

    setTerminalHistory([
      {
        type: "input",
        text: startCmd,
      },
      {
        type: "system",
        text: `${getTimeStamp()} System: Initializing ${selectedLanguage} environment...\n`,
      },
    ]);

    const prompt = `You are a raw interactive terminal. Execute this ${selectedLanguage} code.

    Code:
    ${code}

    CRITICAL TERMINAL RULES:
    1. Execute the code and output ONLY the exact standard output.
    2. INPUT HALT: If the code asks for user input (e.g., input(), cin, Scanner), you MUST HALT immediately. Do NOT simulate input.
    3. When halting for input, output the exact prompt text printed so far, and append EXACTLY "[WAIT_FOR_INPUT]" at the very end, and NOTHING ELSE.
       Example 1: If code is 'name = input("Enter name: ")', your EXACT output must be: 'Enter name: [WAIT_FOR_INPUT]'
       Example 2: If code is 'print("Hello"); x = input()', your EXACT output must be: 'Hello\\n[WAIT_FOR_INPUT]'
    4. ABSOLUTELY NO CONVERSATION. Do not say "The code requests user input" or "I will halt". Output ONLY the terminal text.
    5. NO MARKDOWN. Do not wrap output in \`\`\` blocks.
    6. GUI/AUDIO: If used, place HTML strictly between [GUI_START] and [GUI_END].
    7. COMPILER ERRORS: Prefix with exactly [ERROR] followed by the stack trace.`;

    try {
      const result = await callGroq(prompt);
      let cleanedResult = result
        .replace(/```[a-zA-Z]*\n?/g, "")
        .replace(/```/g, "")
        .trimStart();

      let isErrorOutput = false;
      if (cleanedResult.startsWith("[ERROR]")) {
        isErrorOutput = true;
        cleanedResult = cleanedResult.replace("[ERROR]", "").trim();
        const errLine = parseErrorLine(cleanedResult, selectedLanguage);
        if (errLine) setErrorLine(errLine);
      }

      let guiContent = null;
      if (!isErrorOutput) {
        const guiMatch = cleanedResult.match(
          /\[GUI_START\]([\s\S]*?)\[GUI_END\]/
        );
        if (guiMatch) {
          guiContent = guiMatch[1].trim();
          cleanedResult = cleanedResult
            .replace(/\[GUI_START\][\s\S]*?\[GUI_END\]/, "")
            .trim();
        } else if (
          cleanedResult.includes("<html") ||
          cleanedResult.includes("<!DOCTYPE html>")
        ) {
          const startIdx = cleanedResult.indexOf("<html");
          if (startIdx !== -1) {
            guiContent = cleanedResult.substring(startIdx).trim();
            cleanedResult = "[GUI Generated Successfully]";
          }
        }
      }

      setGuiPreviewHtml(guiContent);

      if (cleanedResult.includes("[WAIT_FOR_INPUT]")) {
        cleanedResult = cleanedResult.replace("[WAIT_FOR_INPUT]", "");
        setTerminalHistory((prev) =>
          [
            ...prev,
            { type: isErrorOutput ? "error" : "output", text: cleanedResult },
          ].slice(-150)
        ); // MEMORY GUARD
        setIsWaitingForInput(true);
      } else {
        setTerminalHistory((prev) =>
          [
            ...prev,
            {
              type: isErrorOutput ? "error" : "output",
              text:
                cleanedResult +
                (guiContent ? `\n\n[System]: GUI Render Initialized.` : "") +
                (isErrorOutput
                  ? `\n\n${getTimeStamp()} Process exited with errors.`
                  : `\n\n${getTimeStamp()} Process exited with code 0.`),
            },
          ].slice(-150)
        ); // MEMORY GUARD
      }
    } catch (err) {
      setTerminalHistory((prev) =>
        [
          ...prev,
          {
            type: "error",
            text: `\n${getTimeStamp()} Execution Error: ${err.message}`,
          },
        ].slice(-150)
      );
    } finally {
      setIsRunning(false);
    }
  };

  const stopExecution = () => {
    if (!isRunning && !isWaitingForInput) return;
    setIsRunning(false);
    setIsWaitingForInput(false);
    setTerminalHistory((prev) => [
      ...prev,
      {
        type: "error",
        text: `\n${getTimeStamp()} Process manually terminated.`,
      },
    ]);
  };

  const clearTerminal = () => {
    setTerminalHistory([]);
    setGuiPreviewHtml(null);
  };

  const handleTerminalInput = async (e) => {
    if (penaltyLockTimeStr) return;

    if (e.key === "ArrowUp") {
      e.preventDefault();
      if (cmdIndex < cmdHistory.length - 1) {
        const newIdx = cmdIndex + 1;
        setCmdIndex(newIdx);
        setTerminalInputValue(cmdHistory[cmdHistory.length - 1 - newIdx]);
      }
      return;
    }

    if (e.key === "ArrowDown") {
      e.preventDefault();
      if (cmdIndex > 0) {
        const newIdx = cmdIndex - 1;
        setCmdIndex(newIdx);
        setTerminalInputValue(cmdHistory[cmdHistory.length - 1 - newIdx]);
      } else if (cmdIndex === 0) {
        setCmdIndex(-1);
        setTerminalInputValue("");
      }
      return;
    }

    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      const inputVal = terminalInputValue;
      setTerminalInputValue("");

      if (inputVal.trim() !== "") {
        setCmdHistory((prev) => [...prev, inputVal]);
        setCmdIndex(-1);
      }

      if (!isWaitingForInput && !isRunning) {
        if (inputVal.trim() === "") return;
        if (inputVal.trim() === "clear") {
          setTerminalHistory([]);
          return;
        }

        const bashCmd = inputVal.trim();
        if (
          bashCmd === "python main.py" ||
          bashCmd === "java Main" ||
          bashCmd === "./a.out" ||
          bashCmd === "run"
        ) {
          runCodeInteractive();
          return;
        }

        setTerminalHistory((prev) => [
          ...prev,
          { type: "input", text: inputVal },
          {
            type: "error",
            text: `bash: ${inputVal.split(" ")[0]}: command not found\n`,
          },
        ]);
        return;
      }

      if (isWaitingForInput) {
        setIsWaitingForInput(false);
        setIsRunning(true);

        const newHistory = [
          ...terminalHistory,
          { type: "program_input", text: inputVal + "\n" },
        ];
        setTerminalHistory(newHistory);

        const historyText = newHistory
          .filter((h) => h.type === "program_input" || h.type === "output")
          .map((h) =>
            h.type === "program_input"
              ? `[USER INPUT]: ${h.text}`
              : `[PROGRAM OUTPUT]: ${h.text}`
          )
          .join("\n");

        const prompt = `You are a raw interactive terminal. Continue executing this ${selectedLanguage} code from where it paused.

          Code:
          ${code}

          History of execution so far:
          ${historyText}

          CRITICAL TERMINAL RULES:
          1. Continue execution exactly from the state after receiving the last [USER INPUT].
          2. Output ONLY the NEW standard output produced. Do NOT repeat previous outputs.
          3. INPUT HALT: If it requires ANOTHER input, HALT immediately and append EXACTLY "[WAIT_FOR_INPUT]" at the end.
          4. ABSOLUTELY NO CONVERSATION. Do not explain the continuation. Output ONLY the raw terminal text.
          5. NO MARKDOWN. Do not wrap output in \`\`\` blocks.
          6. GUI/AUDIO: If used, place HTML strictly between [GUI_START] and [GUI_END].
          7. COMPILER ERRORS: Prefix with exactly [ERROR] followed by the stack trace.`;

        try {
          const result = await callGroq(prompt);
          let cleanedResult = result
            .replace(/```[a-zA-Z]*\n?/g, "")
            .replace(/```/g, "")
            .trimStart();

          let isErrorOutput = false;
          if (cleanedResult.startsWith("[ERROR]")) {
            isErrorOutput = true;
            cleanedResult = cleanedResult.replace("[ERROR]", "").trim();
            const errLine = parseErrorLine(cleanedResult, selectedLanguage);
            if (errLine) setErrorLine(errLine);
          }

          let guiContent = null;
          if (!isErrorOutput) {
            const guiMatch = cleanedResult.match(
              /\[GUI_START\]([\s\S]*?)\[GUI_END\]/
            );
            if (guiMatch) {
              guiContent = guiMatch[1].trim();
              cleanedResult = cleanedResult
                .replace(/\[GUI_START\][\s\S]*?\[GUI_END\]/, "")
                .trim();
            } else if (
              cleanedResult.includes("<html") ||
              cleanedResult.includes("<!DOCTYPE html>")
            ) {
              const startIdx = cleanedResult.indexOf("<html");
              if (startIdx !== -1) {
                guiContent = cleanedResult.substring(startIdx).trim();
                cleanedResult = "[GUI Generated Successfully]";
              }
            }
          }

          setGuiPreviewHtml(guiContent);

          if (cleanedResult.includes("[WAIT_FOR_INPUT]")) {
            cleanedResult = cleanedResult.replace("[WAIT_FOR_INPUT]", "");
            setTerminalHistory((prev) =>
              [
                ...prev,
                {
                  type: isErrorOutput ? "error" : "output",
                  text: cleanedResult,
                },
              ].slice(-150)
            ); // MEMORY GUARD
            setIsWaitingForInput(true);
          } else {
            setTerminalHistory((prev) =>
              [
                ...prev,
                {
                  type: isErrorOutput ? "error" : "output",
                  text:
                    cleanedResult +
                    (isErrorOutput
                      ? `\n\n${getTimeStamp()} Process exited with errors.`
                      : `\n\n${getTimeStamp()} Process exited with code 0.`),
                },
              ].slice(-150)
            ); // MEMORY GUARD
          }
        } catch (err) {
          setTerminalHistory((prev) =>
            [
              ...prev,
              {
                type: "error",
                text: `\n${getTimeStamp()} Execution Error: ${err.message}`,
              },
            ].slice(-150)
          );
        } finally {
          setIsRunning(false);
        }
      }
    }
  };

  const copyTerminalOutput = () => {
    const text = terminalHistory.map((h) => h.text).join("");
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const submitSolution = async (currentQuestion) => {
    if (penaltyLockTimeStr) return;
    if (!code.trim()) return showMessage("Code is empty.", "error");

    setTerminalTab("bash");
    setIsTerminalVisible(true);
    setIsSubmitting(true);
    setTerminalHistory([
      {
        type: "system",
        text: `candidate@csjmu-machine:~/workspace$ ./submit_eval\nPackaging code and running AI assessment...\n`,
      },
    ]);

    let timeTakenSeconds = 0;
    if (userData.testStartTime) {
      timeTakenSeconds = Math.floor(
        (Date.now() - userData.testStartTime.toMillis()) / 1000
      );
    }
    const cheatFlags = userData.tabSwitches || 0;

    const prompt = `Act as an expert computer science professor and automated grading system.

    Problem Statement:
    Title: ${currentQuestion.title}
    Description:
    ${currentQuestion.description}

    Student's Code (${selectedLanguage}):
    ${code}

    Student's Exam Telemetry:
    - Time Elapsed: ${timeTakenSeconds} seconds
    - Cheating Warnings (Tab Switches): ${cheatFlags}

    CRITICAL INSTRUCTIONS:
    1. Analyze the student's code and determine if it correctly solves the problem described. Look for exactness in logic, lines, variables, and syntax. Ensure all complex libraries are understood.
    2. Simulate the execution of the code and determine the exact console output.
    3. GUI & AUDIO SUPPORT: If the code utilizes GUI libraries (e.g., Tkinter, Pygame, PyQt, wxPython, Java Swing, JavaFX, C++ Qt, GTK) or sounds (.wav), you MUST generate a pixel-perfect functional HTML/CSS/JS simulation of the UI and include it in the 'guiHtml' field. It must look ditto to the real app.
    4. Calculate the Final Score (0-10):
       - Base the score heavily on code exactness, accuracy, and structural correctness (up to 10 points).
       - DEDUCTION: Deduct points if the Time Elapsed is excessively long for a problem of this complexity.
       - DEDUCTION: Deduct at least 2 points for EACH Cheating Warning recorded.
       - Cap the final score between 0 and 10.
    5. Provide concise feedback explaining why the code is correct/incorrect, explicitly mentioning any score deductions caused by timing or cheating flags.
    6. STRICTLY NO CONVERSATION IN THE OUTPUT FIELD. If the code produces no console output, the 'output' JSON field MUST be an empty string "". Do not explain the code in the output field.

    You MUST respond STRICTLY with a valid JSON object matching this exact schema, with no additional text or markdown formatting outside the JSON:
    {
      "isCorrect": true or false,
      "score": number (0-10),
      "output": "simulated console output here",
      "feedback": "brief feedback explanation here",
      "guiHtml": "HTML simulation code here, or empty string if no GUI"
    }`;

    try {
      const result = await callGroq(prompt);

      let jsonStr = result
        .replace(/```json\n?/gi, "")
        .replace(/```/g, "")
        .trim();
      const startIdx = jsonStr.indexOf("{");
      const endIdx = jsonStr.lastIndexOf("}");
      if (startIdx !== -1 && endIdx !== -1) {
        jsonStr = jsonStr.substring(startIdx, endIdx + 1);
      }

      const evalData = JSON.parse(jsonStr);

      const isCorrect = evalData.isCorrect;
      const awardedScore = evalData.score || 0;
      const finalOutput = evalData.output || "";
      const aiFeedback = evalData.feedback || "";
      const extractedGuiHtml = evalData.guiHtml || "";

      const isLastQuestion = currentIndex + 1 >= questions.length;

      await addDoc(collection(db, "submissions"), {
        uid: user.uid,
        username: userData.username,
        language: selectedLanguage,
        question: `[${currentQuestion.title}]\n${currentQuestion.description}`,
        questionId: currentQuestion.id,
        code,
        output: finalOutput,
        feedback: aiFeedback,
        awardedScore: awardedScore,
        guiHtml: extractedGuiHtml,
        isCorrect,
        timeTaken: timeTakenSeconds,
        timestamp: serverTimestamp(),
      });

      const userUpdatePayload = {
        score: increment(awardedScore),
        currentQuestionIndex: increment(1),
      };

      if (isLastQuestion && !userData.completionTime) {
        userUpdatePayload.completionTime = timeTakenSeconds;
      }

      await updateDoc(doc(db, "users", user.uid), userUpdatePayload);

      // Student Blind Submission - Just notify them it's submitted
      setTerminalHistory((prev) =>
        [
          ...prev,
          {
            type: "system",
            text: `\n[Submission Status]: Code recorded securely.\nStatus: Pending Final Admin Review.\nMoving to next module...\n`,
          },
        ].slice(-150)
      ); // MEMORY GUARD

      showMessage("Module submitted successfully.", "success");

      if (user?.uid) {
        localStorage.removeItem(`draft_code_${user.uid}_${currentQuestion.id}`);
        setCode(defaultCode[selectedLanguage] || "");
      }
    } catch (err) {
      setTerminalHistory((prev) =>
        [
          ...prev,
          {
            type: "error",
            text: `\n${getTimeStamp()} Submission Error: Evaluator failed to parse code. Please try again.`,
          },
        ].slice(-150)
      ); // MEMORY GUARD
    } finally {
      setIsSubmitting(false);
    }
  };

  const isTestComplete =
    currentIndex >= questions.length && questions.length > 0;

  if (!userData?.testStartTime && !isTestComplete) {
    return (
      <div className="flex-1 flex items-center justify-center p-4 bg-[#f4f4f5] dark:bg-[#09090b]">
        <div className="bg-white dark:bg-[#18181b] border border-zinc-200 dark:border-zinc-800 rounded-[2rem] p-10 max-w-lg text-center shadow-sm">
          <div className="w-20 h-20 bg-zinc-100 dark:bg-zinc-900 rounded-full flex items-center justify-center mx-auto mb-6">
            <Clock size={32} className="text-zinc-900 dark:text-zinc-100" />
          </div>
          <h2 className="text-2xl font-bold text-zinc-900 dark:text-zinc-100 mb-3">
            Begin Examination
          </h2>
          <p className="text-zinc-500 dark:text-zinc-400 mb-8 text-sm leading-relaxed px-4">
            You are allocated{" "}
            <strong>{userData?.testDurationMinutes || 90} minutes</strong>. Once
