            active.
          </p>
          <button
            onClick={handleStartTest}
            disabled={fetchingQuestions}
            className="w-full bg-zinc-900 dark:bg-zinc-100 text-white dark:text-zinc-900 py-4 rounded-xl font-bold text-sm transition-all disabled:opacity-50"
          >
            {fetchingQuestions ? (
              <Loader2 className="animate-spin mx-auto" size={18} />
            ) : (
              "Start Test Now"
            )}
          </button>
        </div>
      </div>
    );
  }

  if (isTestComplete) {
    const formattedTime = userData.completionTime
      ? `${Math.floor(userData.completionTime / 60)}m ${
          userData.completionTime % 60
        }s`
      : "Unknown";
    return (
      <div className="flex-1 flex items-center justify-center p-4 bg-[#f4f4f5] dark:bg-[#09090b]">
        <div className="bg-white dark:bg-[#18181b] border border-zinc-200 dark:border-zinc-800 rounded-[2rem] p-10 max-w-lg text-center shadow-sm">
          <div className="w-24 h-24 bg-emerald-50 dark:bg-emerald-900/20 rounded-full flex items-center justify-center mx-auto mb-6">
            <Trophy
              size={40}
              className="text-emerald-600 dark:text-emerald-400"
            />
          </div>
          <h2 className="text-2xl font-bold text-zinc-900 dark:text-zinc-100 mb-3">
            Evaluation Complete
          </h2>
          <p className="text-zinc-500 dark:text-zinc-400 text-sm mb-6 px-4">
            All assigned module challenges have been submitted successfully.
          </p>
          <div className="inline-flex items-center gap-2 bg-zinc-100 dark:bg-zinc-900 border border-zinc-200 dark:border-zinc-800 text-zinc-600 dark:text-zinc-400 px-4 py-2 rounded-lg font-mono font-bold text-xs">
            <Clock size={14} /> Completion Time: {formattedTime}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex-1 flex flex-col min-h-0 bg-[#f4f4f5] dark:bg-[#09090b] relative">
      {penaltyLockTimeStr && (
        <div className="absolute inset-0 z-50 bg-white/90 dark:bg-black/90 backdrop-blur-md flex flex-col items-center justify-center animate-in fade-in">
          <div className="bg-white dark:bg-[#18181b] border border-red-200 dark:border-red-900/50 p-10 rounded-[2rem] flex flex-col items-center text-center max-w-md shadow-xl">
            <div className="w-20 h-20 bg-red-100 dark:bg-red-900/20 rounded-full flex items-center justify-center mb-6">
              <Lock size={32} className="text-red-600 dark:text-red-500" />
            </div>
            <h2 className="text-2xl font-bold text-zinc-900 dark:text-zinc-100 mb-3 tracking-tight">
              Access Suspended
            </h2>
            <p className="text-zinc-500 dark:text-zinc-400 text-sm mb-8 leading-relaxed px-4">
              A security violation was detected. Your workstation is temporarily
              frozen.
            </p>
            <div className="text-4xl font-mono font-bold text-red-600 dark:text-red-500 tracking-widest">
              {penaltyLockTimeStr}
            </div>
          </div>
        </div>
      )}

      {guiPreviewHtml && (
        <DraggableGUIWindow
          title={`Application Preview - ${selectedLanguage.toUpperCase()}`}
          html={guiPreviewHtml}
          onClose={() => setGuiPreviewHtml(null)}
        />
      )}

      {/* WORKSPACE HEADER */}
      <div className="h-auto py-3 lg:h-14 flex-shrink-0 border-b border-zinc-200 dark:border-zinc-800 bg-white dark:bg-[#18181b] flex flex-wrap items-center justify-between px-4 lg:px-6 z-10">
        <div className="flex items-center gap-3">
          <span className="bg-zinc-100 dark:bg-zinc-900 text-zinc-800 dark:text-zinc-200 border border-zinc-200 dark:border-zinc-800 px-3 py-1.5 rounded-md text-[10px] font-bold uppercase tracking-widest flex items-center gap-2 shadow-sm">
            <Code2 size={12} /> {selectedLanguage}
          </span>
          <span className="text-zinc-500 font-bold text-[10px] uppercase tracking-widest hidden sm:inline-block">
            Module {currentIndex + 1}/{questions.length}
          </span>
        </div>

        <div
          className={`flex items-center gap-2 px-4 py-1.5 rounded-full font-mono font-bold text-xs shadow-sm transition-colors ${
            timeExpired
              ? "bg-red-100 dark:bg-red-900/20 text-red-600 dark:text-red-400 border border-red-200 dark:border-red-900/30"
              : "bg-zinc-100 dark:bg-zinc-900 text-zinc-700 dark:text-zinc-300 border border-zinc-200 dark:border-zinc-800"
          }`}
        >
          <Clock size={14} className={timeExpired ? "animate-pulse" : ""} />
          {timeExpired ? "TIME EXPIRED" : timeLeftStr || "00:00:00"}
        </div>

        <div className="flex items-center gap-2 sm:gap-3 w-full sm:w-auto mt-2 sm:mt-0">
          <button
            onClick={() => setIsQuestionVisible(!isQuestionVisible)}
            className="p-1.5 text-zinc-500 hover:text-zinc-900 dark:hover:text-zinc-100 bg-zinc-100 dark:bg-zinc-800/50 hover:bg-zinc-200 dark:hover:bg-zinc-800 rounded-md transition-colors mr-2"
            title={
              isQuestionVisible ? "Hide Problem Spec" : "Show Problem Spec"
            }
          >
            {isQuestionVisible ? (
              <PanelRightClose size={16} />
            ) : (
              <PanelRightOpen size={16} />
            )}
          </button>

          {activeQuestion && (
            <button
              onClick={handleTopTestCaseRun}
              disabled={
                isRunningTests ||
                isRunning ||
                timeExpired ||
                !!penaltyLockTimeStr
              }
              className="flex-1 sm:flex-none bg-blue-50 dark:bg-blue-900/20 hover:bg-blue-100 dark:hover:bg-blue-900/40 text-blue-700 dark:text-blue-400 border border-blue-200 dark:border-blue-800/50 px-4 py-1.5 rounded-lg text-xs font-bold flex items-center justify-center gap-2 transition-colors disabled:opacity-50 shadow-sm"
              title="Run code against test cases"
            >
              {isRunningTests ? (
                <Loader2 size={12} className="animate-spin" />
              ) : (
                <Beaker size={12} />
              )}{" "}
              Run Test Cases
            </button>
          )}

          <button
            onClick={runCodeInteractive}
            disabled={isRunning || timeExpired || !!penaltyLockTimeStr}
            className="flex-1 sm:flex-none bg-white dark:bg-[#09090b] hover:bg-zinc-50 dark:hover:bg-zinc-900 text-zinc-800 dark:text-zinc-200 border border-zinc-200 dark:border-zinc-800 px-4 py-1.5 rounded-lg text-xs font-bold flex items-center justify-center gap-2 transition-colors disabled:opacity-50 shadow-sm"
            title="Run Custom Interactive Console (Ctrl+Enter)"
          >
            {isRunning ? (
              <Loader2 size={12} className="animate-spin text-zinc-400" />
            ) : (
              <Play size={12} className="text-zinc-900 dark:text-zinc-100" />
            )}{" "}
            Run
          </button>
          <button
            onClick={() => submitSolution(activeQuestion)}
            disabled={
              isSubmitting ||
              timeExpired ||
              !activeQuestion ||
              !!penaltyLockTimeStr
            }
            className="flex-1 sm:flex-none bg-zinc-900 dark:bg-zinc-100 hover:bg-zinc-800 dark:hover:bg-white text-white dark:text-zinc-900 px-4 py-1.5 rounded-lg text-xs font-bold flex items-center justify-center gap-2 transition-colors disabled:opacity-50 shadow-sm"
          >
            {isSubmitting ? (
              <Loader2 size={12} className="animate-spin" />
            ) : (
              <Send size={12} />
            )}{" "}
            Submit
          </button>
        </div>
      </div>

      {/* WORKSPACE PANES */}
      <div className="flex-1 flex flex-row min-h-0 w-full overflow-hidden relative">
        {/* LEFT PANE: Editor + Terminal */}
        <div className="flex-1 flex flex-row bg-[#1e1e1e] min-w-0 h-full relative border-r border-zinc-200 dark:border-zinc-800">
          {/* VS CODE ACTIVITY BAR */}
          <div className="hidden sm:flex w-12 bg-[#181818] border-r border-[#222] flex-col items-center py-4 gap-6 flex-shrink-0 z-20">
            <div className="relative group cursor-pointer w-full flex justify-center">
              <div className="absolute left-0 top-[-4px] bottom-[-4px] w-[2px] bg-blue-500"></div>
              <FileText size={22} className="text-white" />
            </div>
            <Search
              size={22}
              className="text-[#858585] hover:text-white cursor-pointer transition-colors"
            />
            <Code2
              size={22}
              className="text-[#858585] hover:text-white cursor-pointer transition-colors"
            />
            <div className="mt-auto flex flex-col gap-6 mb-2">
              <User
                size={22}
                className="text-[#858585] hover:text-white cursor-pointer transition-colors"
              />
              <Settings
                size={22}
                className="text-[#858585] hover:text-white cursor-pointer transition-colors"
              />
            </div>
          </div>

          {/* MAIN EDITOR & TERMINAL COLUMN */}
          <div className="flex-1 flex flex-col min-w-0 h-full">
            {/* VS CODE TABS */}
            <div className="flex items-center justify-between bg-[#2d2d2d] h-9 border-b border-[#111111] overflow-hidden select-none flex-shrink-0 pr-2">
              <div className="flex items-center h-full">
                <div className="flex gap-1.5 px-4 items-center h-full border-r border-[#444] bg-[#222]">
                  <div className="w-3 h-3 rounded-full bg-[#ff5f56]"></div>
                  <div className="w-3 h-3 rounded-full bg-[#ffbd2e]"></div>
                  <div className="w-3 h-3 rounded-full bg-[#27c93f]"></div>
                </div>
                <div className="flex items-center px-4 h-full bg-[#1e1e1e] border-t-2 border-blue-500 text-[#cccccc] text-[13px] font-mono gap-2 min-w-[120px]">
                  <Code2 size={14} className="text-blue-400" />
                  {selectedLanguage === "python"
                    ? "main.py"
                    : selectedLanguage === "java"
                    ? "Main.java"
                    : selectedLanguage === "c++"
                    ? "main.cpp"
                    : "main.c"}
                </div>
              </div>
              <div className="flex items-center gap-1 bg-[#1e1e1e] px-2 py-1 rounded-md border border-[#333]">
                <button
                  onClick={() => setFontSize((f) => Math.max(10, f - 1))}
                  className="p-1 hover:bg-[#3c3c3c] text-[#858585] hover:text-[#cccccc] rounded transition-colors"
                  title="Zoom Out"
                >
                  <ZoomOut size={14} />
                </button>
                <span className="text-[#858585] text-[10px] font-mono w-6 text-center">
                  {fontSize}
                </span>
                <button
                  onClick={() => setFontSize((f) => Math.min(24, f + 1))}
                  className="p-1 hover:bg-[#3c3c3c] text-[#858585] hover:text-[#cccccc] rounded transition-colors"
                  title="Zoom In"
                >
                  <ZoomIn size={14} />
                </button>
                <div className="w-px h-4 bg-[#444] mx-1"></div>
                <button
                  onClick={runCodeInteractive}
                  disabled={isRunning || timeExpired || !!penaltyLockTimeStr}
                  className="p-1 hover:bg-[#3c3c3c] text-emerald-500 hover:text-emerald-400 rounded transition-colors disabled:opacity-50"
                  title="Run Code"
                >
                  <Play size={14} fill="currentColor" />
                </button>
                <button
                  onClick={resetEditorCode}
                  title="Reset Code Template"
                  className="p-1 hover:bg-[#3c3c3c] text-[#858585] hover:text-[#cccccc] rounded transition-colors"
                >
                  <RotateCcw size={14} />
                </button>
              </div>
            </div>

            {/* BREADCRUMBS */}
            <div className="flex items-center px-4 h-6 bg-[#1e1e1e] text-[#858585] text-[11px] font-mono gap-1.5 shadow-sm z-10 select-none flex-shrink-0">
              <span>workspace</span>
              <ChevronRight size={12} />
              <span>src</span>
              <ChevronRight size={12} />
              <span className="text-[#cccccc]">
                {selectedLanguage === "python"
                  ? "main.py"
                  : selectedLanguage === "java"
                  ? "Main.java"
                  : selectedLanguage === "c++"
                  ? "main.cpp"
                  : "main.c"}
              </span>
            </div>

            {/* EDITOR */}
            <div
              className={`flex-1 flex flex-col relative min-h-0 ${
                isTerminalMaximized ? "hidden" : "block"
              }`}
            >
              <div className="flex-1 flex relative overflow-hidden">
                <div
                  ref={lineNumbersRef}
                  className="w-12 sm:w-14 flex-shrink-0 bg-[#161616] border-r border-[#333333] flex flex-col items-end pr-3 sm:pr-4 py-4 m-0 leading-[1.6] font-mono select-none overflow-hidden"
                  style={{ fontSize: `${fontSize}px` }}
                >
                  {Array.from({
                    length: Math.max(50, code.split("\n").length + 10),
                  }).map((_, i) => (
                    <div
                      key={i}
                      className={`${
                        errorLine === i + 1
                          ? "text-red-500 font-bold"
                          : activeLine === i + 1
                          ? "text-[#c6c6c6]"
                          : "text-[#666666]"
                      }`}
                    >
                      {i + 1}
                    </div>
                  ))}
                </div>
