}

// --- ADMIN PANEL COMPONENT ---
function AdminView({ showMessage }) {
  const [activeTab, setActiveTab] = useState("dashboard");
  const [scoreAdjustment, setScoreAdjustment] = useState(5);
  const [submissions, setSubmissions] = useState([]);
  const [students, setStudents] = useState([]);
  const [questions, setQuestions] = useState([]);
  const [loading, setLoading] = useState(true);

  // Search State
  const [searchTerm, setSearchTerm] = useState("");

  // Grouped Submission State
  const [inspectUid, setInspectUid] = useState(null);
  const [inspectIndex, setInspectIndex] = useState(0);

  const [expandedStudentId, setExpandedStudentId] = useState(null);

  // Added Admin State to view submitted GUI applications inline
  const [adminGuiPreviewOpen, setAdminGuiPreviewOpen] = useState(false);
  const [isGeneratingGui, setIsGeneratingGui] = useState(false);
  const [isReEvaluating, setIsReEvaluating] = useState(false);

  // Question Form State
  const [qBankFilter, setQBankFilter] = useState("python");
  const [editingQId, setEditingQId] = useState(null);
  const [qTitle, setQTitle] = useState("");
  const [qDesc, setQDesc] = useState("");
  const [qExpectedInput, setQExpectedInput] = useState("");
  const [qExpectedOutput, setQExpectedOutput] = useState("");
  const [qLanguage, setQLanguage] = useState("python");

  const [isAddingQuestion, setIsAddingQuestion] = useState(false);
  const [confirmResetAll, setConfirmResetAll] = useState(false);

  const [globalKey, setGlobalKey] = useState("");
  const [updatingKey, setUpdatingKey] = useState(false);

  useEffect(() => {
    const subQ = query(
      collection(db, "submissions"),
      orderBy("timestamp", "asc")
    );
    const unsubSubs = onSnapshot(subQ, (snapshot) =>
      setSubmissions(
        snapshot.docs.map((doc) => ({ id: doc.id, ...doc.data() }))
      )
    );
    const userQ = query(
      collection(db, "users"),
      where("role", "==", "student")
    );
    const unsubUsers = onSnapshot(userQ, (snapshot) =>
      setStudents(snapshot.docs.map((doc) => ({ id: doc.id, ...doc.data() })))
    );
    const questQ = query(
      collection(db, "questions"),
      orderBy("createdAt", "asc")
    );
    const unsubQuest = onSnapshot(questQ, (snapshot) => {
      setQuestions(snapshot.docs.map((doc) => ({ id: doc.id, ...doc.data() })));
      setLoading(false);
    });
    return () => {
      unsubSubs();
      unsubUsers();
      unsubQuest();
    };
  }, []);

  const groupedSubmissions = useMemo(() => {
    const groups = {};
    submissions.forEach((sub) => {
      if (!groups[sub.uid]) {
        groups[sub.uid] = {
          uid: sub.uid,
          username: sub.username,
          language: sub.language,
          latestTimestamp: sub.timestamp,
          subs: [],
        };
      }
      groups[sub.uid].subs.push(sub);
      if (
        sub.timestamp &&
        (!groups[sub.uid].latestTimestamp ||
          sub.timestamp > groups[sub.uid].latestTimestamp)
      ) {
        groups[sub.uid].latestTimestamp = sub.timestamp;
      }
    });
    let result = Object.values(groups).sort(
      (a, b) => b.latestTimestamp - a.latestTimestamp
    );

    if (searchTerm) {
      result = result.filter(
        (g) =>
          g.username.toLowerCase().includes(searchTerm.toLowerCase()) ||
          g.uid.includes(searchTerm)
      );
    }
    return result;
  }, [submissions, searchTerm]);

  const filteredStudents = useMemo(() => {
    if (!searchTerm) return students;
    return students.filter(
      (s) =>
        s.username.toLowerCase().includes(searchTerm.toLowerCase()) ||
        s.email.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [students, searchTerm]);

  const currentGroup = useMemo(
    () => groupedSubmissions.find((g) => g.uid === inspectUid),
    [groupedSubmissions, inspectUid]
  );
  const selectedSubmission = currentGroup?.subs[inspectIndex] || null;

  useEffect(() => {
    if (currentGroup && inspectIndex >= currentGroup.subs.length) {
      setInspectIndex(Math.max(0, currentGroup.subs.length - 1));
    }
  }, [currentGroup, inspectIndex]);

  useEffect(() => {
    setAdminGuiPreviewOpen(false);
  }, [inspectIndex, inspectUid]);

  const generateKeyForUser = async (userId) => {
    try {
      const newKey = Math.random().toString(36).substring(2, 8).toUpperCase();
      await updateDoc(doc(db, "users", userId), { accessKey: newKey });
      showMessage(`Key generated: ${newKey}`, "success");
    } catch (err) {
      showMessage("Failed to generate key.", "error");
    }
  };

  const handleUpdateKey = async () => {
    if (!globalKey) return showMessage("Key cannot be empty.", "error");
    setUpdatingKey(true);
    try {
