                              {student.tabSwitches > 0 ? (
                                <button
                                  onClick={() =>
                                    setExpandedStudentId(
                                      expandedStudentId === student.id
                                        ? null
                                        : student.id
                                    )
                                  }
                                  className="text-red-600 dark:text-red-400 flex items-center gap-2 font-bold bg-red-100 dark:bg-red-500/10 border border-red-200 dark:border-red-500/20 px-3 py-1.5 rounded-xl text-xs transition-colors hover:bg-red-200 dark:hover:bg-red-500/20 shadow-sm cursor-pointer"
