                                      className="text-[11px] font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-100 dark:bg-emerald-500/10 hover:bg-emerald-200 dark:hover:bg-emerald-500/20 px-3 py-2 rounded-lg flex items-center gap-1.5 transition-colors"
                                    >
                                      <Unlock size={14} /> Unlock Exam
                                    </button>
