                    return (
                      <tr
                        key={group.uid}
                        onClick={() => {
                          setInspectUid(group.uid);
                          setInspectIndex(0);
                        }}
                        className="hover:bg-zinc-50 dark:hover:bg-zinc-800/30 transition-colors cursor-pointer group hover:shadow-inner"
                      >
                        <td className="p-5 font-bold text-sm text-zinc-900 dark:text-zinc-100">
                          <div className="flex items-center gap-3">
                            <div className="p-2 bg-zinc-100 dark:bg-zinc-800 rounded-full text-zinc-400 group-hover:text-blue-500 transition-colors">
                              <User size={16} />
                            </div>
                            <div className="flex flex-col">
                              <span>{group.username}</span>
                              <span className="text-[10px] font-mono font-normal text-zinc-500 uppercase tracking-widest">
                                ID: {group.uid.substring(0, 8)}
                              </span>
                            </div>
                          </div>
