                        <td className="p-5 text-right">
                          <button className="text-zinc-400 group-hover:text-blue-500 transition-colors bg-zinc-50 dark:bg-zinc-900 px-4 py-2 rounded-xl border border-transparent group-hover:border-blue-200 dark:group-hover:border-blue-900/50 flex items-center gap-2 ml-auto text-xs font-bold">
                            <FileText size={14} /> View Code
                          </button>
                        </td>
                      </tr>
                    );
                  })}
