                  <button
                    onClick={() =>
                      setInspectIndex((i) =>
                        Math.min(currentGroup.subs.length - 1, i + 1)
                      )
                    }
                    disabled={inspectIndex === currentGroup.subs.length - 1}
                    className="p-1.5 rounded-lg text-zinc-600 dark:text-zinc-400 hover:bg-white dark:hover:bg-zinc-600 hover:text-zinc-900 dark:hover:text-white disabled:opacity-30 disabled:hover:bg-transparent transition-colors shadow-sm disabled:shadow-none"
                    title="Next Question"
                  >
                    <ChevronRight size={16} />
                  </button>
                </div>
              </div>

