                <div className="flex items-center gap-1.5 bg-white dark:bg-zinc-900 border border-zinc-200 dark:border-zinc-800 p-1.5 rounded-xl shadow-sm">
                  <span className="text-[10px] font-bold uppercase tracking-widest text-zinc-400 px-2 hidden lg:inline">
                    Adjust Score:
                  </span>
                  <input
                    type="number"
                    min="1"
                    max="100"
                    value={scoreAdjustment}
                    onChange={(e) =>
                      setScoreAdjustment(Number(e.target.value) || 0)
