                    title={`Deduct ${scoreAdjustment} Pts`}
                  >
                    <Minus size={14} />
                    <span className="hidden sm:inline">Deduct</span>
                  </button>
                </div>
                <button
                  onClick={() => {
                    setInspectUid(null);
                    setInspectIndex(0);
