                AI Score Awarded:
              </span>
              <span className="font-mono bg-blue-100 dark:bg-blue-900/30 text-blue-700 dark:text-blue-400 px-2 py-0.5 rounded font-bold">
                {selectedSubmission.awardedScore !== undefined
                  ? selectedSubmission.awardedScore
                  : selectedSubmission.isCorrect
                  ? 10
                  : 0}{" "}
                / 10
              </span>

              <div className="w-px h-4 bg-zinc-300 dark:bg-zinc-700 mx-2"></div>

              <span className="font-bold text-zinc-500 uppercase tracking-widest text-[10px]">
                Status:
              </span>
              {selectedSubmission.isCorrect ? (
                <span className="text-emerald-600 dark:text-emerald-400 font-bold flex items-center gap-1">
                  <CheckCircle size={12} /> Pass
                </span>
              ) : (
                <span className="text-red-600 dark:text-red-400 font-bold flex items-center gap-1">
                  <XCircle size={12} /> Fail
                </span>
              )}
            </div>

            {/* Split Content Area: STRICTLY LEFT/RIGHT */}
            <div className="flex-1 flex flex-col md:flex-row min-h-0 overflow-hidden bg-[#fafafa] dark:bg-[#0a0a0a]">
              {/* MODAL LEFT: Code Snapshot */}
              <div className="w-full md:w-1/2 flex flex-col border-b md:border-b-0 md:border-r border-zinc-200 dark:border-zinc-800 h-1/2 md:h-full flex-shrink-0 md:flex-shrink">
                <div className="p-4 border-b border-zinc-200 dark:border-zinc-800/80 bg-white dark:bg-[#0d0d0f] text-[10px] font-bold text-zinc-400 uppercase tracking-widest flex items-center gap-2 flex-shrink-0 shadow-sm z-10">
                  <Code2 size={14} /> Written Source
                </div>
                <div className="flex-1 overflow-auto p-4 sm:p-6 custom-scrollbar relative bg-[#1e1e1e]">
                  <pre
                    className="font-mono text-[13px] sm:text-[14px] leading-[1.6] text-[#d4d4d4] inline-block min-w-full m-0 whitespace-pre"
                    dangerouslySetInnerHTML={{
                      __html: highlightCode(
                        selectedSubmission.code,
                        selectedSubmission.language
                      ),
                    }}
                  />
                </div>
              </div>

              {/* MODAL RIGHT: Execution Evaluation Panel & GUI */}
              <div className="w-full md:w-1/2 flex flex-col min-h-0 bg-white dark:bg-[#0d0d0f] h-1/2 md:h-full relative">
                <div className="p-4 border-b border-zinc-200 dark:border-zinc-800/80 bg-zinc-50 dark:bg-[#0a0a0a] text-[10px] font-bold text-zinc-400 uppercase tracking-widest flex items-center justify-between flex-shrink-0">
                  <div className="flex items-center gap-2">
                    <BookOpen size={14} /> Target Problem:{" "}
                    <span className="text-blue-500 font-bold">
                      {extractTitle(selectedSubmission.question)}
                    </span>
                  </div>
                  <button
                    onClick={handleReEvaluate}
                    disabled={isReEvaluating}
                    className="text-[10px] bg-purple-100 text-purple-700 dark:bg-purple-900/30 dark:text-purple-400 hover:bg-purple-200 px-3 py-1.5 rounded-lg font-bold uppercase tracking-widest transition-colors flex items-center gap-1.5 disabled:opacity-50"
                  >
                    {isReEvaluating ? (
                      <Loader2 size={12} className="animate-spin" />
                    ) : (
                      <RefreshCw size={12} />
                    )}
                    AI Re-Evaluate
                  </button>
                </div>

                {/* SCROLLABLE EVALUATION AREA */}
                <div className="flex-1 overflow-auto p-4 sm:p-6 custom-scrollbar flex flex-col gap-6 relative">
                  {/* AI Feedback Panel */}
                  <div className="bg-purple-50/50 dark:bg-purple-950/10 border border-purple-200 dark:border-purple-900/30 p-5 rounded-2xl flex-shrink-0 shadow-sm relative overflow-hidden">
                    <div className="absolute -right-6 -top-6 text-purple-200/50 dark:text-purple-900/20">
                      <BrainCircuit size={100} />
                    </div>
                    <h4 className="text-[10px] font-bold text-purple-600 dark:text-purple-400 uppercase tracking-widest mb-3 flex items-center gap-2 relative z-10">
                      <BrainCircuit size={14} /> Expert AI Feedback
                    </h4>
                    <p className="text-sm text-zinc-700 dark:text-zinc-300 leading-relaxed relative z-10">
                      {selectedSubmission.feedback ||
                        "No feedback generated for this legacy submission."}
                    </p>
                  </div>

                  {/* Question Detail */}
                  <div className="bg-zinc-50 dark:bg-[#18181b] border border-zinc-200 dark:border-zinc-800 p-4 rounded-2xl flex-shrink-0">
                    <h4 className="text-[10px] font-bold text-zinc-500 uppercase tracking-widest mb-3">
                      Original Problem Description
                    </h4>
                    <div className="text-sm">
                      {renderQuestionContent(
                        selectedSubmission.question.replace(/^\[.*?\]\n?/, "")
                      )}
                    </div>
                  </div>

                  {/* Execution Results */}
                  <div
                    className={`p-4 rounded-2xl border flex-shrink-0 ${
                      selectedSubmission.isCorrect
                        ? "bg-emerald-50/30 dark:bg-emerald-950/5 border-emerald-200 dark:border-emerald-900/50"
                        : "bg-red-50/30 dark:bg-red-950/5 border-red-200 dark:border-red-900/50"
                    }`}
                  >
                    <h4
                      className={`text-[10px] font-bold uppercase tracking-widest mb-3 flex items-center gap-1.5 ${
                        selectedSubmission.isCorrect
                          ? "text-emerald-600 dark:text-emerald-400"
                          : "text-red-600 dark:text-red-400"
                      }`}
                    >
                      <MonitorSmartphone size={12} /> Student's Output
                    </h4>
                    <div className="bg-[#1e1e1e] p-4 rounded-xl overflow-x-auto">
                      <pre
                        className={`font-mono text-[13px] leading-[1.6] whitespace-pre ${
                          selectedSubmission.isCorrect
                            ? "text-emerald-400"
                            : "text-red-400"
                        }`}
                      >
                        {selectedSubmission.output}
                      </pre>
                    </div>
                  </div>

                  {/* ADMIN GUI ENGINE */}
                  <div className="mt-auto border-t border-zinc-200 dark:border-zinc-800 pt-6 flex flex-col gap-4 flex-shrink-0">
                    <div className="flex flex-col xl:flex-row xl:items-center justify-between gap-4">
                      <div>
                        <h4 className="text-sm font-bold text-zinc-900 dark:text-zinc-100 flex items-center gap-2 tracking-tight">
                          <AppWindow size={16} className="text-blue-500" /> App
                          Viewer
                        </h4>
                        <p className="text-[10px] text-zinc-500 mt-1 uppercase tracking-widest font-bold">
                          See the student's app
                        </p>
                      </div>

                      <div className="flex flex-wrap items-center gap-2">
                        {selectedSubmission.guiHtml && (
                          <button
                            onClick={() => {
                              setAdminGuiPreviewOpen(true);
                            }}
                            className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-xl text-xs font-bold transition-all shadow-sm flex items-center gap-2"
                          >
                            <Maximize2 size={14} /> Open App Window
                          </button>
                        )}

                        {hasGuiLibraries && (
                          <button
                            onClick={handleForceGenerateGui}
                            disabled={isGeneratingGui}
                            className="px-4 py-2 bg-zinc-900 dark:bg-zinc-100 text-white dark:text-zinc-900 hover:bg-zinc-800 dark:hover:bg-white rounded-xl text-xs font-bold transition-all shadow-sm flex items-center gap-2 disabled:opacity-50"
                            title="Force AI to generate UI simulation if missing"
                          >
                            {isGeneratingGui ? (
                              <Loader2 size={14} className="animate-spin" />
                            ) : (
                              <RefreshCw size={14} />
                            )}
                            Generate GUI Again
                          </button>
                        )}
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* ADMIN GUI PREVIEW WINDOW */}
      {selectedSubmission &&
        selectedSubmission.guiHtml &&
        adminGuiPreviewOpen && (
          <DraggableGUIWindow
            title={`App Testing: File ${inspectIndex + 1} - ${
              currentGroup.username
            }`}
            html={selectedSubmission.guiHtml}
            onClose={() => setAdminGuiPreviewOpen(false)}
          />
        )}
    </div>
  );
}

// --- LEADERBOARD COMPONENT ---
function LeaderboardView() {
  const [leaders, setLeaders] = useState([]);

  useEffect(() => {
    const q = query(collection(db, "users"), orderBy("score", "desc"));
    const unsubscribe = onSnapshot(q, (snapshot) => {
      const allUsers = snapshot.docs.map((doc) => ({
        id: doc.id,
        ...doc.data(),
      }));
      setLeaders(allUsers.filter((u) => u.role !== "admin"));
    });
    return () => unsubscribe();
  }, []);

  const downloadCSV = () => {
    const headers = ["Rank,Candidate Name,Points"];
    const rows = leaders.map((l, i) => `${i + 1},${l.username},${l.score}`);
    const csvContent =
      "data:text/csv;charset=utf-8," + headers.concat(rows).join("\n");
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", "Exam_Leaderboard.csv");
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="flex-1 p-4 sm:p-8 overflow-y-auto custom-scrollbar bg-[#f4f4f5] dark:bg-[#09090b]">
      <div className="max-w-4xl mx-auto py-8">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-10 border-b border-zinc-200 dark:border-zinc-800 pb-8">
          <div className="flex items-center gap-4">
            <div className="p-4 bg-zinc-900 dark:bg-white rounded-[1.5rem] shadow-sm">
              <Trophy className="text-white dark:text-zinc-900" size={28} />
            </div>
            <h1 className="text-2xl sm:text-3xl font-extrabold text-zinc-900 dark:text-zinc-100 tracking-tight">
              Global Standings
            </h1>
          </div>
          <button
            onClick={downloadCSV}
            className="flex items-center gap-2 bg-white dark:bg-[#18181b] border border-zinc-200 dark:border-zinc-800 hover:bg-zinc-50 dark:hover:bg-zinc-900 text-zinc-700 dark:text-zinc-300 px-4 py-2.5 rounded-xl text-sm font-bold shadow-sm transition-colors w-max"
          >
            <Download size={16} /> Export Data
          </button>
        </div>
        <div className="bg-white dark:bg-[#18181b] border border-zinc-200 dark:border-zinc-800 rounded-[2rem] shadow-sm overflow-hidden">
          <table className="w-full text-left">
            <thead className="bg-zinc-50 dark:bg-[#0f0f11] border-b border-zinc-200 dark:border-zinc-800">
              <tr>
                <th className="p-5 sm:p-6 text-[10px] font-bold text-zinc-500 uppercase tracking-widest">
                  Position
                </th>
                <th className="p-5 sm:p-6 text-[10px] font-bold text-zinc-500 uppercase tracking-widest">
                  Candidate
                </th>
                <th className="p-5 sm:p-6 text-[10px] font-bold text-zinc-500 uppercase tracking-widest text-right">
                  Points
                </th>
              </tr>
            </thead>
            <tbody className="divide-y divide-zinc-100 dark:divide-zinc-800/50">
              {leaders.map((leader, index) => (
                <tr
                  key={leader.id}
                  className="hover:bg-zinc-50 dark:hover:bg-zinc-800/30 transition-colors"
                >
                  <td className="p-5 sm:p-6 font-bold text-sm">
                    {index === 0 ? (
                      <span className="inline-flex items-center gap-2 bg-yellow-100 dark:bg-yellow-500/10 text-yellow-700 dark:text-yellow-500 px-3 py-1.5 rounded-lg">
                        <Trophy size={14} /> Gold
                      </span>
                    ) : index === 1 ? (
                      <span className="inline-flex items-center gap-2 bg-zinc-100 dark:bg-zinc-800 text-zinc-600 dark:text-zinc-300 px-3 py-1.5 rounded-lg border border-zinc-200 dark:border-zinc-700">
                        Silver
                      </span>
                    ) : index === 2 ? (
                      <span className="inline-flex items-center gap-2 bg-amber-100 dark:bg-amber-900/30 text-amber-700 dark:text-amber-600 px-3 py-1.5 rounded-lg">
                        Bronze
                      </span>
                    ) : (
                      <span className="text-zinc-400 pl-4">{index + 1}</span>
                    )}
                  </td>
                  <td className="p-5 sm:p-6 font-bold text-zinc-900 dark:text-zinc-100 text-base">
                    {leader.username}
                  </td>
                  <td className="p-5 sm:p-6 text-right font-mono text-emerald-600 dark:text-emerald-400 font-bold text-base">
                    {leader.score}
                  </td>
                </tr>
              ))}
              {leaders.length === 0 && (
                <tr>
                  <td
                    colSpan="3"
                    className="p-12 text-center text-zinc-400 text-sm"
                  >
                    Standings are currently empty.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}
